        [$imp_pb, $cfg_pb] = self::configurazionePubblicazioni();
        $passi_pb = $cfg_pb->passiVisibili();
        $appr_pb = (bool) ($imp_pb['approvazione_attiva'] ?? false); // con l'approvazione accesa il percorso della richiesta ha un passo in più

        return [
            'studente' => [
                'titolo' => 'Studente', 'icona' => 'fa-user-graduate', 'colore' => '#0056B3',
