                'sezioni' => [
                    ['titolo' => 'Prendere in carico e capire il percorso', 'immagine' => 'ref_scheda.png', 'didascalia' => 'In alto l’iter della pratica con la persona in carico; sotto «Passa al passo successivo».',
                     'passi' => ['Dalla «Scrivania» o da «Pratiche degli studenti» apri una pratica: il riquadro verde dice cosa fare ora.', 'L’iter mostra i passi (protocollo, ufficio del corso, segreteria…) e chi ha in carico la pratica: i passi dell’iter sono diversi da modulo a modulo.', 'Se manca qualcosa scrivi un messaggio allo studente («Storico e messaggi»): riceve una email e risponde dalla pratica. Le note interne le vedi solo tu.', 'Quando hai finito premi «Passa al passo successivo». Se serve puoi passarla a un altro ufficio o a un operatore.']],
                    ['titolo' => 'Certificati con marche da bollo', 'immagine' => 'ref_marche.png', 'didascalia' => 'Il riquadro «Marche da bollo» guida i tre momenti: carica su Esse3, avvisa lo studente, registra il pagamento.',
                     'passi' => ['1. Carica le 2 marche da bollo su Esse3 (Segreteria, Situazione tasse) e premi «Marche caricate su Esse3: avvisa lo studente».', '2. Quando il pagamento risulta, spunta «marca da bollo assolta virtualmente» e carica il certificato generato da Esse3 (PDF).', '3. Premi «Al Direttore»: il Direttore riceve il link per firmare in PAdES; poi lo studente scarica e stampa il certificato e tu ricevi l’avviso.', 'Per il Diploma Supplement non c’è la marca: carichi il documento da far firmare e la pratica va al Direttore.']],
                    ['titolo' => 'Attestati, mobilità e altre pratiche', 'passi' => ['<b>Attestati (frequenza, esame):</b> l’ufficio attestati controlla l’attestato in PDF preparato dal portale, lo manda al Direttore e, dopo la firma, registra il protocollo in uscita: lo studente scarica il PDF protocollato.', '<b>Mobilità internazionale:</b> prima passa dall’ufficio Internazionalizzazione, poi dal referente del corso, quindi va nel verbale e alla segreteria.', '<b>Tesi:</b> arriva dopo la conferma del relatore. <b>Convalide, piani di studio, esoneri, trasferimenti:</b> dopo l’istruttoria si portano in seduta.', 'Dopo la decisione del Consiglio la pratica va alla segreteria studenti, che registra l’esito sulla carriera.']],
                ],
            ],
            'consiglio' => [
                'titolo' => 'Referente del consiglio e segretario', 'icona' => 'fa-gavel', 'colore' => '#15803d',
                'a_chi' => 'Per chi gestisce le sedute di un consiglio di corso di studio: presenze, decisioni sulle pratiche, verbale e firme.',
                'in_breve' => 'Ogni seduta ha un percorso a sette tappe, uguale per tutti i consigli: il portale propone sempre il passo successivo. Il verbale esce in Word, come il modello, e si firma in PAdES dal segretario e dal coordinatore.',
                'sezioni' => [
                    ['titolo' => 'Preparare la seduta', 'immagine' => 'ref_sedute.png', 'didascalia' => 'L’elenco delle sedute del tuo consiglio.',
                     'passi' => ['In Didattica scegli «Sedute e verbali» e crea la seduta: consiglio, data, ora, luogo, ordine del giorno (un punto per riga).', 'I componenti si inseriscono una volta sola dall’anagrafe di Ateneo e ogni seduta riparte da lì.', 'Facoltativo: manda la convocazione. Ogni componente ha un link personale per giustificare l’assenza, che finisce da sola nelle presenze.']],
                    ['titolo' => 'Le sette tappe', 'immagine' => 'ref_seduta.png', 'didascalia' => 'La seduta guidata: si vede subito cosa è fatto e cosa manca.',
                     'passi' => ['<b>Presenze:</b> presente, assente giustificato o ingiustificato, con i pulsanti «tutti presenti».', '<b>Cosa è stato detto:</b> un riquadro di testo per ogni punto dell’ordine del giorno. Le pratiche studenti portano già le loro decisioni.', '<b>Pratiche e decisioni:</b> esito per ogni pratica (approvata, con modifiche, respinta, rinviata) e testo della delibera.', '<b>Esiti agli studenti:</b> «Applica gli esiti» aggiorna le pratiche e avvisa gli studenti con l’estratto del verbale.', '<b>Verbale:</b> scarichi il Word, lo completi se serve e lo salvi in PDF.', '<b>Firme:</b> carichi il PDF e indichi le email di segretario e coordinatore: ricevono un link personale e firmano uno dopo l’altro. Se la firma tarda parte un sollecito ogni pochi giorni (fino a tre); puoi mandarlo anche tu.']],
                    ['titolo' => 'Dopo la firma', 'passi' => ['Il verbale firmato va ai referenti del consiglio e resta nell’archivio dei verbali, con ricerca nel testo.', 'Le pratiche lavorate passano alla segreteria studenti insieme al verbale.']],
                ],
            ],
            'risorsa' => [
                'titolo' => 'Responsabile di risorsa', 'icona' => 'fa-user-shield', 'colore' => '#0f766e',
                'a_chi' => 'Per chi è indicato come responsabile di un’aula, di un laboratorio o di un mezzo.',
                'in_breve' => 'Ricevi le richieste di prenotazione e le approvi dal portale, controlli quanto la risorsa è usata e tieni sotto controllo le scadenze (bollo, assicurazione, tarature). Per le auto e i mezzi controlli anche il diario di bordo.',
                'sezioni' => [
                    ['titolo' => 'Approvare le richieste', 'immagine' => 'resp_risorse.png', 'didascalia' => '«Le mie risorse»: richieste da approvare e prenotazioni in arrivo.',
                     'passi' => ['Nella tua Area personale apri «Le mie risorse»: vedi quante richieste aspettano una risposta.', 'Per ogni richiesta puoi approvare o rifiutare: chi ha prenotato riceve l’email. Le richieste che aspettano da una settimana compaiono anche nel cruscotto del Direttore.', 'Se una prenotazione viene annullata o rifiutata, il primo in lista d’attesa per quello slot è avvisato da solo.']],
                    ['titolo' => 'Il cruscotto della risorsa', 'immagine' => 'resp_cruscotto.png', 'didascalia' => 'Prenotazioni, ore, utilizzo, fasce più richieste, chi la usa di più e le scadenze.',
                     'passi' => ['Dal cruscotto scegli il periodo e vedi prenotazioni, ore prenotate, percentuale di utilizzo e le fasce orarie più richieste: servono a decidere se serve più disponibilità.', '«Chi la usa di più» e le quantità consumate aiutano a pianificare. Il pulsante «Excel» scarica tutti i numeri.', 'Nella sezione «Scadenze» vedi bollo, assicurazione, revisione, taratura: prima della data e il giorno della scadenza ricevi un avviso. Quando rinnovi scrivi la nuova data e premi «Rinnovata».']],
                    ['titolo' => 'Diario di bordo (auto e mezzi)', 'passi' => ['Chi prenota un mezzo compila il diario dopo l’uso (km, rifornimenti, segnalazioni); i km iniziali si propongono dall’ultimo viaggio.', 'Tu controlli e correggi dal registro del mezzo; ogni correzione azzera la verifica. Puoi scaricare l’Excel mensile o annuale.']],
                ],
            ],
            'scuola' => [
                'titolo' => 'Scuole: la convenzione FSL', 'icona' => 'fa-school', 'colore' => '#B30000',
                'a_chi' => 'Per le scuole che prenotano attività di Formazione Scuola Lavoro e devono stipulare (o rinnovare) la convenzione con il Dipartimento: dirigenti, segreterie e docenti referenti.',
                'in_breve' => 'Compili i dati della scuola e il portale prepara la Convenzione e l’Allegato A. Il Dirigente firma la Convenzione in PAdES, la scuola carica i file e il Dipartimento fa il resto: protocollo in entrata, firma del Direttore e protocollo definitivo. A ogni passaggio ricevi una email e le prenotazioni in attesa si confermano da sole. La convenzione vale un anno.',
                'sezioni' => [
                    ['titolo' => 'Prima di cominciare', 'passi' => ['Prenota le attività di Formazione Scuola Lavoro dal sito. Se la scuola non ha ancora una convenzione valida, la prenotazione resta in attesa e si conferma da sola quando la convenzione diventa attiva.', 'Ti arriva una email con il link personale alla pagina della convenzione; puoi anche aprirla con il codice della prenotazione.', 'Serve la firma digitale del Dirigente Scolastico.']],
                    ['titolo' => 'Compilare i dati della scuola', 'immagine' => 'fsl_modulo.png', 'didascalia' => 'La pagina della convenzione: istituzione scolastica, Dirigente e attività dell’Allegato A.',
                     'passi' => ['Apri il link ricevuto per email.', '<b>Istituzione scolastica:</b> denominazione, codice meccanografico, comune, indirizzo, codice fiscale, PEC e email della scuola.', '<b>Dirigente Scolastico:</b> nome, codice fiscale, luogo e data di nascita.', '<b>Attività dell’Allegato A:</b> per ogni attività prenotata indichi il numero di studenti e il docente tutor.', 'Premi il pulsante per preparare i documenti. Puoi tornare sulla stessa pagina dal link e correggere i dati: i documenti si aggiornano.']],
                    ['titolo' => 'Scaricare i documenti', 'immagine' => 'fsl_documenti_pronti.png', 'didascalia' => '«I documenti sono pronti»: l’Allegato A in PDF e la Convenzione in Word, con le istruzioni dei passi successivi.',
                     'passi' => ['Scarica l’<b>Allegato A (PDF)</b> e la <b>Convenzione (Word)</b>.', 'Controlla i dati. Eventuali correzioni si fanno nel Word; poi salva la Convenzione in PDF.'],
                     'nota' => 'Conserva la email con il link: serve per tornare sulla pagina e seguire la pratica.'],
                    ['titolo' => 'La firma del Dirigente', 'passi' => ['Il Dirigente firma la Convenzione in PDF <b>in formato PAdES</b> (un PDF firmato). Il formato CAdES (file .p7m) non è accettato.', 'Dopo la firma il file non va più modificato né salvato di nuovo: il portale controlla che la firma sia integra.', 'L’Allegato A si carica in PDF, anche senza firma digitale.', 'In alternativa al caricamento si può inviare tutto dalla PEC della scuola alla PEC del Dipartimento (dipartimento.best@pec.unical.it).']],
                    ['titolo' => 'Caricare la convenzione firmata', 'immagine' => 'fsl_firmata_caricata.png', 'didascalia' => 'Il riquadro «Convenzione firmata» conferma la ricezione, con data e firmatario.',
                     'passi' => ['Nella stessa pagina scegli il PDF firmato e l’Allegato A e premi il pulsante di caricamento.', 'Compare la conferma di ricezione e ti arriva la email «Convenzione ricevuta».', 'Se hai sbagliato file puoi sostituirlo con uno nuovo finché il Dipartimento non lo ha preso in carico.']],
                    ['titolo' => 'Che cosa fa il Dipartimento', 'immagine' => 'fsl_presa_in_carico.png', 'didascalia' => 'Il Dipartimento ha preso in carico la convenzione: la pagina mostra il protocollo in entrata.',
                     'passi' => ['<b>Presa in carico:</b> l’ufficio registra il protocollo in entrata e ti scrive (email «Convenzione presa in carico»).', '<b>Firma del Direttore:</b> la convenzione va al Direttore, che firma in PAdES. Tu non devi fare nulla.', '<b>Protocollo definitivo:</b> l’ufficio registra il protocollo e la validità: la convenzione diventa attiva e le prenotazioni in attesa si confermano.', 'Se c’è un problema l’ufficio <b>rifiuta il file con un motivo</b>: ricevi l’email «Convenzione da correggere», correggi e carichi di nuovo il file.']],
                    ['titolo' => 'La convenzione è attiva', 'immagine' => 'fsl_attiva.png', 'didascalia' => 'La pagina conferma che la convenzione è firmata dal Direttore e protocollata.',
                     'passi' => ['Ricevi l’email «Convenzione attiva».', 'Le prenotazioni in attesa della scuola sono confermate.']],
                    ['titolo' => 'Dove ritrovarla', 'immagine' => 'fsl_area_attiva.png', 'didascalia' => 'Area personale, scheda «Programma FSL»: la convenzione in vigore, con protocollo e validità, e i documenti da scaricare.',
                     'passi' => ['Tutti i docenti collegati alla scuola vedono e scaricano la convenzione firmata e l’Allegato A dalla scheda «Programma FSL» dell’Area personale.', 'La convenzione vale <b>un anno</b>. Poco prima della scadenza il Dipartimento avvisa e si rifà lo stesso percorso con una nuova convenzione; le scadute restano consultabili.']],
                ],
            ],
            'elenco' => [
                'titolo' => 'Docenti delle scuole: l’elenco degli studenti FSL', 'icona' => 'fa-list-ol', 'colore' => '#0f766e',
                'a_chi' => 'Per il docente che ha prenotato un’attività di Formazione Scuola Lavoro per la sua classe e deve consegnare l’elenco dei partecipanti.',
                'in_breve' => 'Dopo la prenotazione, e prima dell’attività, consegni due cose dalla tua Area personale: l’elenco degli studenti (cognome e nome) e l’autorizzazione della scuola in PDF. Con quei nomi il portale prepara gli attestati di partecipazione.',
                'sezioni' => [
                    ['titolo' => 'Aprire la pagina dell’elenco', 'immagine' => 'fsl_elenco_1_area.png', 'didascalia' => 'Area personale, «Prossimi eventi»: sotto la prenotazione c’è il pulsante «Carica elenco e autorizzazione», con la data entro cui consegnare.',
                     'passi' => ['Accedi al portale e apri la tua Area personale.', 'Nella prenotazione dell’attività premi <b>«Carica elenco e autorizzazione»</b>. Accanto vedi la scadenza («entro il …»).', 'Il pulsante è disponibile anche se la convenzione della scuola non è ancora attiva.'],
                     'nota' => 'Se la scadenza si avvicina e manca qualcosa, il portale ti manda promemoria periodici e un ultimo avviso.'],
                    ['titolo' => 'La pagina dei documenti', 'immagine' => 'fsl_elenco_2_pagina.png', 'didascalia' => 'In alto i documenti ancora da consegnare (studenti inseriti e autorizzazione); sotto, a sinistra l’elenco a mano, a destra l’autorizzazione e il modello Excel.',
                     'passi' => ['In alto un riepilogo: quanti studenti hai inserito sul totale iscritto («0 / 15 studenti»), se manca l’autorizzazione e la data entro cui consegnare.', 'Quando tutto è completo compare «Documenti completi».']],
                    ['titolo' => 'Inserire i nomi a mano', 'immagine' => 'fsl_elenco_4_compilato.png', 'didascalia' => 'Una riga per studente: cognome e nome. In fondo il conteggio e «Salva l’elenco».',
                     'passi' => ['Scrivi <b>cognome</b> e <b>nome</b> di ogni studente, una riga per studente.', 'Servono altre righe? Premi «Aggiungi studente». Per toglierne una usa la X rossa.', 'Hai l’elenco in Excel? Seleziona le due colonne, copia e incolla nella prima casella libera: le righe si riempiono da sole.', 'Premi <b>«Salva l’elenco»</b>. Puoi tornare e correggerlo quando vuoi.'],
                     'nota' => 'Ogni studente deve avere cognome e nome. Non puoi inserire più studenti di quelli indicati nell’iscrizione: per aumentare il numero chiedi alla segreteria.'],
                    ['titolo' => 'Oppure usare il modello Excel', 'immagine' => 'fsl_elenco_3_excel.png', 'didascalia' => 'Riquadro «Usa il modello Excel»: scarica, compila, carica.',
                     'passi' => ['Premi <b>«Scarica il modello»</b> e compila le colonne Cognome e Nome.', 'Salva il file e caricalo con <b>«Carica e sostituisci»</b> (file .xlsx o .csv).', 'Il file <b>sostituisce</b> l’elenco attuale: il portale te lo chiede prima di procedere.']],
                    ['titolo' => 'Controllare che sia salvato', 'immagine' => 'fsl_elenco_5_salvato.png', 'didascalia' => 'Dopo il salvataggio il riepilogo mostra «5 / 15 studenti» e i nomi restano nelle righe.',
                     'passi' => ['Il contatore in alto si aggiorna (qui «5 / 15 studenti»).', 'Se ti manca ancora qualche nome puoi aggiungerlo più tardi, finché non sono stati inviati gli attestati.']],
                    ['titolo' => 'L’autorizzazione della scuola', 'passi' => ['Nel riquadro «Autorizzazione della scuola» scegli il PDF (al massimo 10 MB) e premi <b>«Carica l’autorizzazione»</b>.', 'Puoi aprirla per controllarla, sostituirla con un altro PDF o toglierla.', 'A elenco e autorizzazione consegnati compare «Documenti completi».']],
                    ['titolo' => 'Dopo l’attività: gli attestati', 'passi' => ['I nomi servono a generare gli attestati di partecipazione, che partono dopo l’attività (per le classi con presenza registrata).', 'Dopo l’invio degli attestati l’elenco non è più modificabile dal docente: per correggere un nome scrivi alla segreteria.']],
                ],
            ],
            'tutor' => [
                'titolo' => 'Tutor', 'icona' => 'fa-user-pen', 'colore' => '#b45309',
                'a_chi' => 'Per chi ha vinto un bando di tutorato: lettera d’incarico, registro delle attività e compenso.',
                'in_breve' => 'Confermi l’incarico con SPID o CIE, indichi i dati per il pagamento, registri le attività svolte e, a fine attività, il docente firma la dichiarazione e l’ufficio pagamenti procede.',
                'sezioni' => [
                    ['titolo' => 'L’incarico', 'immagine' => 'tutorato_1_dati_pagamento.png', 'didascalia' => 'Dati per il pagamento nella dichiarazione individuale.',
                     'passi' => ['Ricevi una email con il link alla lettera d’incarico: apri, controlla e conferma con SPID o CIE (livello 2).', 'Compili online la dichiarazione individuale: l’IBAN viene conservato cifrato.', 'La lettera è firmata dal docente e dal Direttore: ricevi il documento firmato e il protocollo.']],
                    ['titolo' => 'Registro e fine attività', 'immagine' => 'tutorato_7_area_personale.png', 'didascalia' => 'L’Area personale del tutor.',
                     'passi' => ['Nel registro scrivi le attività svolte, con data e ore. Il compenso in lettera lo calcola il portale (ore × 25 euro lordi per l’ente, diviso 1,24); se fai meno ore viene ricalcolato.', 'A fine attività richiedi la dichiarazione di fine attività: il docente titolare approva le ore e la firma, poi il referente del tutorato controlla ore e compenso e passa la pratica ai pagamenti.', 'L’ufficio pagamenti riceve la pratica e registra il pagamento: vedi lo stato dalla tua Area personale.']],
                ],
            ],
            'azienda' => [
                'titolo' => 'Enti e aziende: la convenzione per la tesi', 'icona' => 'fa-handshake', 'colore' => '#047857',
                'a_chi' => 'Per gli enti e le aziende che accolgono studenti del Dipartimento per la tesi e devono stipulare la convenzione: legali rappresentanti, uffici del personale e referenti.',
                'in_breve' => 'Non serve registrarsi. Chiedi la convenzione con la tua email, ricevi un link personale, inserisci i dati dell’azienda, scarichi la convenzione già compilata, la firmi digitalmente (PAdES) e la ricarichi. Al resto pensa il Dipartimento: protocollo, firma del Direttore e archivio. Se vuoi cambiare qualche articolo puoi proporlo nella stessa pagina.',
                'sezioni' => [
                    ['titolo' => 'Chiedere la convenzione', 'immagine' => 'tesi_5_richiesta_pubblica.png', 'didascalia' => 'La pagina pubblica per chiedere la convenzione: nome dell’ente, email e una domanda di controllo.',
                     'passi' => ['Apri la pagina «Convenzione di tesi per enti e aziende» (dal sito del Dipartimento, menu Studenti → Tesi) oppure l’indirizzo che ti ha dato il Dipartimento.', 'Scrivi il nome dell’ente o dell’azienda e un’email (meglio quella dell’ufficio che segue la pratica), rispondi alla domanda di controllo e premi «Inviami il link».', 'Se il Dipartimento ti ha già invitato, il link è nella email che hai ricevuto: salta questo passaggio.'],
                     'nota' => 'Il link è personale: puoi chiudere la pagina e riprendere più tardi dallo stesso link. Se lo perdi, richiedilo di nuovo con la stessa email: ricevi il link della convenzione già aperta.'],
                    ['titolo' => 'Inserire i dati', 'immagine' => 'tesi_2_azienda_modulo.png', 'didascalia' => 'La pagina della convenzione: dati dell’azienda, rappresentante legale e, sotto, gli articoli.',
                     'passi' => ['<b>Dati dell’ente:</b> ragione sociale, partita IVA o codice fiscale, sede legale, PEC; facoltativi settore e sito.', '<b>Rappresentante legale:</b> nome e cognome e la qualifica (per esempio Amministratore Unico): è la persona che firma.', '<b>Elenco pubblico:</b> se spunti il consenso, l’azienda compare nell’elenco delle aziende convenzionate sul sito del Dipartimento (nome, comune, settore e sito).', 'Premi «Salva e continua».']],
                    ['titolo' => 'Se vuoi cambiare un articolo', 'passi' => ['Il testo è quello standard del Dipartimento. Apri l’articolo che ti interessa, scegli «Proponi una modifica» e scrivi il testo come lo vorresti.', 'Dopo il salvataggio la convenzione resta ferma: il Dipartimento valuta la proposta e ti scrive. Non puoi firmare finché non risponde.', 'Il Dipartimento può <b>accettare</b>, <b>rifiutare</b> (con la spiegazione) o <b>rispondere con un altro testo</b>. In quest’ultimo caso puoi accettarlo, ritirare la tua modifica o scriverne una nuova.', 'Quando tutte le modifiche sono decise ricevi una email e puoi scaricare la convenzione.'],
                     'nota' => 'Le modifiche concordate compaiono nel PDF e nel Word che scarichi: non devi correggere nulla a mano.'],
                    ['titolo' => 'Scaricare, firmare e ricaricare', 'passi' => ['Premi «Scarica il PDF da firmare» (è anche disponibile il Word). Controlla i dati: se qualcosa non va correggi nella pagina e riscarica.', 'Il legale rappresentante firma il <b>PDF</b> con la <b>firma digitale in formato PAdES</b> (un PDF firmato). Il formato CAdES (file .p7m) non è accettato.', 'Carica il PDF firmato nel riquadro «Firma e ricarica». <b>Dopo la firma il file non va più modificato né salvato di nuovo</b>: il portale controlla che la firma sia integra.', 'Ricevi subito la conferma di ricezione. Se hai sbagliato file puoi sostituirlo finché il Dipartimento non lo ha preso in carico.']],
                    ['titolo' => 'Che cosa fa il Dipartimento e la convenzione stipulata', 'immagine' => 'tesi_4_elenco_pubblico.png', 'didascalia' => 'L’elenco pubblico delle aziende convenzionate per la tesi.',
                     'passi' => ['<b>Presa in carico:</b> l’ufficio protocolla la convenzione e ti scrive. Poi la fa firmare al Direttore: tu non devi fare nulla.', '<b>Se c’è un problema</b> l’ufficio rifiuta il file con un motivo: ricevi la email, correggi e carichi di nuovo.', '<b>Convenzione stipulata:</b> ricevi una email con il protocollo e le date di validità e dalla stessa pagina scarichi la convenzione firmata. Vale <b>cinque anni</b> (art. 10).', 'Se hai dato il consenso, l’azienda compare nell’elenco pubblico delle aziende convenzionate.']],
                    ['titolo' => 'Rinnovare la convenzione', 'passi' => ['Circa due mesi prima della scadenza ricevi una email con il link della convenzione.', 'Dalla pagina premi «Rinnova la convenzione»: i dati sono già inseriti, controllali, scarica e firma la nuova convenzione come la prima volta.']],
                ],
            ],
            'convenzioni_tesi' => [
                'titolo' => 'Ufficio: le convenzioni di tesi', 'icona' => 'fa-file-signature', 'colore' => '#047857',
                'a_chi' => 'Per le persone dell’«Ufficio convenzioni di tesi» (Persone e permessi → Uffici e persone), che invitano le aziende, valutano le modifiche agli articoli e protocollano.',
                'in_breve' => 'Didattica → «Convenzioni di tesi» mostra l’iter in sei passi e, per ogni convenzione, solo ciò che tocca a te: valutare le modifiche agli articoli, protocollare in entrata (il Direttore riceve da solo il link) e protocollare in uscita con la validità. Nell’archivio trovi tutte le convenzioni, anche quelle già in essere.',
                'sezioni' => [
                    ['titolo' => 'Avviare una convenzione', 'immagine' => 'tesi_1_pannello_da_seguire.png', 'didascalia' => 'Il pannello «Da seguire»: i sei passi, chi li fa e le convenzioni che aspettano l’ufficio.',
                     'passi' => ['Da Didattica apri «Convenzioni di tesi». In cima ci sono i sei passi dell’iter con il numero di convenzioni in ciascuno.', 'Per invitare un’azienda scrivi l’email (e il nome, se vuoi) in «Invita un’azienda» e premi «Invia il link»: l’azienda riceve il link per compilare.', 'Oppure dai all’azienda l’indirizzo della pagina pubblica (lo trovi nel riquadro «Pagina per le aziende»): si richiede da sola.']],
                    ['titolo' => 'Valutare le modifiche agli articoli', 'passi' => ['Se l’azienda propone modifiche la convenzione compare in «Modifiche agli articoli da valutare», con il testo standard e la proposta affiancati.', 'Per ogni articolo scegli <b>Accetto</b>, <b>Rifiuto</b> (scrivi sempre il motivo) oppure <b>Rispondo con un altro testo</b> e riscrivilo.', 'Premi «Manda la risposta all’azienda»: la convenzione torna all’azienda, che può firmare solo quando tutte le modifiche sono decise.'],
                     'nota' => 'Per una modifica importante conviene sentire il Direttore prima di accettare: il testo concordato finisce nel documento che l’azienda firma.'],
                    ['titolo' => 'Protocollo in entrata', 'passi' => ['Quando l’azienda carica il PDF firmato compare in «Firmate dalle aziende: da prendere in carico» e ricevi una email.', 'Scarica il PDF, protocollalo nel sistema di Ateneo e scrivi qui numero e data del protocollo in entrata.', 'Premi «Registra e manda al Direttore»: l’azienda riceve l’avviso e il Direttore (o il vice, se è attivo «Direttore assente») riceve l’email con il link per firmare. Non devi ricaricare nulla.', 'Se qualcosa non va, «Rifiuta con un motivo»: l’azienda riceve la spiegazione e ricarica il file.']],
                    ['titolo' => 'La firma del Direttore', 'immagine' => 'tesi_6_direttore_firma.png', 'didascalia' => 'La pagina di firma del Direttore: il PDF dell’azienda e la firma in PAdES.',
                     'passi' => ['Il Direttore firma dal suo link (firma remota oppure scarica, firma e ricarica). Il portale controlla che il PDF sia quello dell’azienda con una firma in più.', 'Se l’email non è partita (per esempio perché il Direttore non è indicato) la convenzione resta «da mandare al Direttore»: controlla la Direzione in Persone e permessi → Uffici e persone e premi «Invia al Direttore».', 'Puoi rimandare il link con «Rimanda il link».']],
                    ['titolo' => 'Protocollo in uscita: convenzione stipulata', 'passi' => ['Quando il Direttore firma la convenzione passa a «Firmate dal Direttore: protocollo in uscita» e ricevi una email.', 'Scarica il PDF firmato, protocollalo e scrivi numero, data e <b>validità</b> (di partenza cinque anni, come dice l’art. 10). Se vuoi carica anche il PDF con la segnatura di protocollo.', 'Premi «Registra: convenzione stipulata»: va in archivio, l’azienda riceve l’avviso e, se ha dato il consenso, compare nell’elenco pubblico.']],
                    ['titolo' => 'Archivio, convenzioni già in essere e rinnovi', 'immagine' => 'tesi_3_archivio.png', 'didascalia' => 'L’archivio: ricerca, filtri valide/scadute, inserimento a mano, rinnovo.',
                     'passi' => ['In «Archivio e aziende convenzionate» cerchi per azienda, protocollo o comune e filtri valide o scadute.', 'Per le convenzioni stipulate prima del portale usa «Inserisci una convenzione già in essere»: ragione sociale, protocollo e validità bastano; il PDF è facoltativo. Con il consenso l’azienda compare nell’elenco pubblico.', 'Due mesi prima della scadenza l’azienda e l’ufficio ricevono un avviso. Con «Rinnova» l’azienda riceve il link con i dati già inseriti.', 'Le aziende ferme da una settimana ricevono un promemoria; dall’elenco «In corso con l’azienda» puoi anche rimandare il link a mano.']],
                ],
            ],
            'direttore' => [
                'titolo' => 'Direttore', 'icona' => 'fa-gauge-high', 'colore' => '#0f2a4a',
                'a_chi' => 'Per il Direttore del Dipartimento: cose da firmare e cose che si sono fermate.',
                'in_breve' => 'Il cruscotto riunisce in una pagina ciò che aspetta la tua firma e ciò che si è fermato nei vari moduli. Non cambia nulla: serve a vedere dove intervenire. Le firme si fanno dal link personale.',
                'sezioni' => [
                    ['titolo' => 'Il cruscotto', 'immagine' => 'dir_cruscotto.png', 'didascalia' => 'Nove gruppi: firme, pratiche ferme, conferme in ritardo, verbali, convenzioni, tutorato, risorse.',
                     'passi' => ['Dall’Area personale premi «Cruscotto del Direttore»: in alto vedi quante cose da guardare ci sono.', 'Ogni gruppo ha il suo numero. Le righe con i giorni in rosso aspettano da sette giorni o più.', 'Premi su una riga per andare direttamente alla pratica, al documento da firmare o alla pagina del modulo.', 'Gruppi: documenti da firmare, convenzioni FSL da firmare, pratiche ferme, conferme dei docenti in ritardo, verbali in attesa di firma, convenzioni in scadenza, pagamenti del tutorato fermi, scadenze delle risorse, prenotazioni da approvare ferme.']],
                    ['titolo' => 'Firmare', 'immagine' => 'dir_firma.png', 'didascalia' => 'La pagina di firma: accedi, controlla il PDF, firma in PAdES.',
                     'passi' => ['Per certificati, attestati, convenzioni e lettere ricevi una email con il link personale (lo trovi anche nel cruscotto).', 'Accedi con le tue credenziali: solo tu puoi aprire il tuo link. Vedi il PDF accanto e firmi con la firma remota oppure scarichi, firmi in PAdES e ricarichi.', 'Il portale controlla che il file sia firmato e che il firmatario corrisponda al codice fiscale indicato. Dopo la firma l’ufficio riceve l’avviso.'],
                     'nota' => 'Il Direttore e il vice direttore si scelgono dall’anagrafe di Ateneo nella Direzione (Persone e permessi → Uffici e persone): valgono per tutte le firme.'],
                    ['titolo' => 'Quando sei assente: il vice', 'passi' => ['Il vice direttore ha gli stessi permessi del Direttore (cruscotto e firme), ma i link di firma e gli avvisi arrivano a te finché non attivi l’interruttore.', 'Dall’Area personale apri la card <b>«Direttore assente»</b>, indica (se vuoi) la data di rientro e premi «Il Direttore è assente: passa al vice»: da quel momento firme, link e riepilogo vanno al vice.', 'Al ritorno premi «Il Direttore è tornato» (se hai indicato la data di rientro l’interruttore si spegne da solo). Lo possono attivare anche il vice e la segreteria di direzione.']],
                ],
            ],
            'assistenza' => [
                'titolo' => 'Assistenza e Didacticus', 'icona' => 'fa-headset', 'colore' => '#B30000',
                'a_chi' => 'Per le persone dell’ufficio «Assistenza» e per chi istruisce Didacticus, l’assistente virtuale del portale.',
                'in_breve' => 'Studenti, personale ed esterni scrivono dal pulsante «Serve aiuto?». Risponde prima Didacticus; quando non basta, la chat arriva a te con un avviso (email e, se vuoi, una finestrella di Windows). Rispondi nella chat, che si aggiorna da sola. Dal pannello insegni a Didacticus nuove risposte, con link e allegati, e vedi cosa non ha saputo dire.',
                'sezioni' => [
                    ['titolo' => 'Rispondere alle chat', 'immagine' => 'ass_coda.png', 'didascalia' => 'La casella: a sinistra le schede Da prendere · Mie · Tutte · Con Didacticus · Chiuse; a destra la chat aperta.',
                     'passi' => ['Apri <b>Didattica → Assistenza</b> (o la voce «Assistenza» nella Scrivania). Il numero sulla voce di menu e sulla scheda «Da prendere» dice quante persone aspettano.', 'Scegli una chat: vedi chi scrive (con accesso o esterno), l’argomento, la pratica collegata e tutta la conversazione, comprese le risposte di Didacticus.', 'Premi <b>«Prendo io»</b> o semplicemente rispondi: la chat passa a te e chi ha scritto lo vede («Ti risponde …»). Invio manda il messaggio, Maiusc+Invio va a capo.', '<b>«Passa a…»</b> gira la chat a un collega dell’ufficio, che riceve subito l’avviso. <b>«Chiudi»</b> la chiude; se la persona riscrive si riapre da sola.', 'Le <b>note interne</b> (spunta «Nota interna») le vedi solo tu e i colleghi: servono per passarsi informazioni. La persona non le vede.'],
                     'nota' => 'Le chat compaiono anche nella casella «Messaggi» in alto, insieme alle conversazioni sulle prenotazioni e sulle convenzioni FSL.'],
                    ['titolo' => 'Una chat in carico', 'immagine' => 'ass_chat.png', 'didascalia' => 'La domanda, la risposta di Didacticus (azzurra), la nota interna (gialla) e la tua risposta.',
                     'passi' => ['Quando una chat arriva da Didacticus trovi una nota che dice perché (la persona ha chiesto un operatore, la risposta non è bastata, non ha trovato risposte) e vedi cosa gli è già stato risposto: non ripeterlo.', 'Se la chat è fuori dagli orari, la persona ha già letto l’avviso con gli orari: rispondi appena puoi, le arriva per email.', 'Se la risposta che dai è una che serve spesso, aggiungila a Didacticus: vedi più sotto.'],
                     'nota' => 'La scheda «Con Didacticus» mostra le chat che sta ancora seguendo lui: puoi aprirle e, se serve, prenderle.'],
                    ['titolo' => 'Notifiche a finestrella su Windows', 'passi' => ['Nella pagina Assistenza premi <b>«Attiva le notifiche su questo computer»</b> e accetta il permesso del browser (Chrome o Edge). Poi premi «Prova»: deve comparire una finestrella.', 'Da quel momento una nuova richiesta o un messaggio nelle tue chat compare come finestrella, anche se la pagina è chiusa (il browser deve essere aperto, anche ridotto a icona). Un clic apre la chat giusta.', 'Puoi <b>silenziare</b> le notifiche per 1 ora, 4 ore o fino a domani, e scegliere <b>«Solo le chat in carico a me»</b> per non sentire le richieste da prendere.', 'Se la finestrella non compare controlla che Windows non sia in «Non disturbare» e che le notifiche di Chrome/Edge siano attive nelle Impostazioni di Windows.'],
                     'nota' => 'Se il portale non ha le chiavi per le notifiche, la barra lo dice e restano le email. Le notifiche non contengono mai dati che non servono a te.'],
                    ['titolo' => 'Orari e servizio', 'passi' => ['In fondo alla pagina Assistenza, «Orari e servizio»: scrivi per ogni giorno gli orari in cui rispondete, per esempio <code>09:00-13:00, 14:00-16:00</code>, e lascia vuoto un giorno senza assistenza.', 'Fuori orario la chat funziona lo stesso: chi scrive vede un avviso con gli orari e riceve la risposta per email. Senza nessun orario il servizio è considerato sempre aperto.', 'L’interruttore «Servizio acceso» spegne tutto: il pulsante «Serve aiuto?» sparisce dal sito e non si aprono nuove chat (quelle in corso restano).']],
                    ['titolo' => 'Statistiche', 'immagine' => 'ass_statistiche.png', 'didascalia' => 'Chat per argomento e per operatore, tempi e utilità, in un periodo a scelta.',
                     'passi' => ['La scheda «Statistiche» mostra quante chat sono arrivate, quante risolte da Didacticus e quante passate agli operatori, il tempo medio di prima risposta e quanti hanno trovato utile l’assistenza.', 'Le due tabelle (per argomento e per operatore) si scaricano con «Scarica» in Excel, PDF o CSV.', 'I numeri non contengono nomi né messaggi: restano anche dopo la cancellazione delle chat vecchie (12 mesi).']],
                    ['titolo' => 'Istruire Didacticus: le voci', 'immagine' => 'did_voci.png', 'didascalia' => 'La base di conoscenza: ogni voce è una risposta, con quante volte è stata usata e quanti l’hanno trovata utile.',
                     'passi' => ['Apri <b>Didattica → Didacticus</b>. Le <b>voci</b> sono tutto quello che sa: Didacticus risponde <b>solo</b> con quello che trovi qui e non inventa nulla.', 'Premi <b>«Nuova voce»</b> (o «Modifica» su una esistente). Con «Spegni» una voce resta salvata ma Didacticus non la usa; con il cestino la elimini.', 'Per scrivere tante voci in una volta: <b>Scarica → CSV</b>, aggiungi righe in Excel (Argomento, Titolo, Domande, Parole chiave, Risposta, Link, Attiva) e riportale con «Importa da CSV». Le voci con lo stesso titolo si aggiornano.']],
                    ['titolo' => 'Come si scrive una voce', 'immagine' => 'did_voce.png', 'didascalia' => 'Una voce: titolo, domande, parole chiave, risposta, link e allegati.',
                     'passi' => ['<b>Domande</b>: una per riga, come le scriverebbe uno studente («Come richiedo il certificato di iscrizione», «Ho bisogno di un certificato»). Più modi scrivi, meglio capisce.', '<b>Parole chiave e sinonimi</b>, separate da virgola: le parole che, se compaiono nella domanda, indicano questa voce («certificato, attestazione, marca da bollo»). Anche frasi di più parole.', '<b>Risposta</b>: scrivi come parleresti a uno studente. Riga vuota = nuovo paragrafo; righe che iniziano con «- » = elenco; <code>**testo**</code> = grassetto; gli indirizzi web diventano link. Non scrivere nomi di persone o dati personali.', '<b>Link</b>: diventano pulsanti sotto la risposta. Metti il testo del pulsante e l’indirizzo (https://… oppure una pagina del portale, per esempio <code>modulistica.php</code>).', '<b>Allegati</b>: moduli da scaricare (PDF, Word, Excel, immagini, fino a 10 MB). Chi chiede li scarica con un clic.', 'Le opzioni: <b>Attiva</b>; <b>Solo per chi ha fatto l’accesso</b> (gli esterni vengono invitati ad accedere); <b>Proponi sempre un operatore</b> per le risposte che spesso non bastano.'],
                     'nota' => 'Non scrivere importi, scadenze o regole che cambiano senza indicare dove trovarle: se cambiano, la voce resta sbagliata finché qualcuno non la corregge. Meglio un link alla fonte ufficiale.'],
                    ['titolo' => 'Provare Didacticus', 'immagine' => 'did_prova.png', 'didascalia' => 'La prova: cosa risponderebbe e le voci più vicine, con il punteggio.',
                     'passi' => ['Nella scheda <b>Prova</b> scrivi una domanda come la scriverebbe uno studente: vedi se Didacticus risponderebbe, proporrebbe delle voci («intendevi…?») o direbbe di non saper rispondere.', 'La tabella mostra le cinque voci più vicine con il punteggio e le parole che ha riconosciuto. Una risposta arriva solo se il punteggio supera la <b>soglia</b> (predefinita 60).', 'Se una domanda va male: aggiungi quella frase alle «Domande» della voce giusta, oppure una parola chiave o un sinonimo, e riprova.']],
                    ['titolo' => 'Imparare da quello che gli viene chiesto', 'immagine' => 'did_mancate.png', 'didascalia' => 'Le domande a cui Didacticus non ha saputo rispondere o la cui risposta non è bastata.',
                     'passi' => ['La scheda <b>«Domande senza risposta»</b> raccoglie le domande che Didacticus non ha saputo gestire e quelle in cui la persona ha detto «Non mi basta». Il numero rosso nel menu dice quante sono da vedere.', 'Premi <b>«Crea una voce»</b>: si apre una voce già con la domanda e, se un operatore aveva risposto a quella chat, con la sua risposta come bozza. Rivedila e salva: la prossima volta Didacticus saprà rispondere.', 'Con <b>«Metti da parte»</b> togli dall’elenco le domande che non servono (si possono rimettere in lista).'],
                     'nota' => 'Le domande si cancellano insieme alle chat dopo 12 mesi.'],
                    ['titolo' => 'Impostazioni e immagine di Didacticus', 'immagine' => 'did_impostazioni.png', 'didascalia' => 'Acceso/spento, saluto, soglia di sicurezza e immagine di profilo.',
                     'passi' => ['<b>Acceso/spento</b>: spento, le nuove chat vanno subito agli operatori come prima.', '<b>Saluto</b>: il primo messaggio di Didacticus (puoi cambiarlo).', '<b>Soglia di sicurezza</b>: più alta = più prudente (risponde meno e passa agli operatori più spesso); più bassa = risponde anche con domande vaghe ma può sbagliare voce. Si consiglia 60; provala con la scheda «Prova».', '<b>Immagine di profilo</b>: puoi caricare un’altra immagine (PNG, JPG o WEBP, quadrata) o tornare al gufo di serie.']],
                ],
            ],
            // La stessa guida, con più parole, è in documentazione/guide/guida_myforms.md: se cambia l’una, cambia anche l’altra
            'myforms' => [
                'titolo' => 'MyForms: creare i moduli', 'icona' => 'fa-clipboard-list', 'colore' => '#be123c',
                'a_chi' => 'Per chi crea moduli online da far compilare (questionari, raccolte di informazioni, iscrizioni) e ne legge le risposte.',
                'in_breve' => 'Scrivi le domande, scegli a chi mandare il modulo e condividi il link o il QR code. Il modulo si chiude da solo alla scadenza o al numero massimo di risposte; le risposte si leggono nel pannello e si scaricano in Excel, e possono cancellarsi da sole dopo il tempo che scegli, con un avviso 7 giorni prima.',
                'sezioni' => [
                    ['titolo' => 'Creare un modulo',
                     'passi' => ['Nel pannello apri <b>MyForms</b> e premi <b>Nuovo form</b>. Scrivi il titolo (obbligatorio) e, se vuoi, una descrizione.', 'Scegli <b>a chi si rivolge</b>, imposta le <b>opzioni</b> e aggiungi le domande con <b>Aggiungi campo</b>. Poi premi <b>Salva</b>: il modulo nasce in <b>bozza</b> e non lo vede nessuno.', 'Con <b>Anteprima</b> lo provi come lo vedrà chi risponde (non salva niente). Quando è pronto premi <b>Apri</b>: il portale non lo apre se mancano il titolo, una domanda o i profili.', 'Con <b>Duplica</b> fai una copia in bozza, senza risposte né co-gestori.']],
                    ['titolo' => 'Le domande e le condizioni',
                     'passi' => ['Per ogni domanda scegli il tipo (testo, email, numero, data, tendina, scelta singola o multipla, sì/no, dichiarazione, allegato, tabella a righe…), la spunta <b>obbligatorio</b> e, se serve, un aiuto. Le opzioni di una tendina o di una scelta si scrivono separate da virgola.', 'Per far comparire una domanda solo in certi casi premi l’icona dei cursori e, in <b>Mostra solo se</b>, scegli la domanda da guardare, il confronto e il valore (per esempio «Sì»).', 'Una domanda nascosta non è mai obbligatoria e la sua risposta non viene salvata: resta vuota.'],
                     'nota' => 'Se cambi o togli domande quando il modulo ha già risposte, le risposte già date restano com’erano.'],
                    ['titolo' => 'A chi si rivolge',
                     'passi' => ['Spunta uno o più profili: chiunque anche senza accesso, chiunque abbia fatto l’accesso, studenti, docenti, personale tecnico amministrativo, personale di Ateneo, esterni, scuole, aziende. Gli amministratori possono sempre aprirlo.', '<b>Attenzione a «Scuole»:</b> ' . \App\Auth\Pubblico::AVVISO_SCUOLE . ' Lo sceglie la persona stessa dalla pagina «Sono una scuola» e il portale non controlla che lo sia davvero.', 'Chi ha un profilo non previsto legge «Questo modulo è riservato a…». Chi non ha fatto l’accesso trova «Accedi per compilare» e poi torna al modulo.', 'Se il modulo è aperto a chiunque, chi non ha fatto l’accesso risponde a una domanda di controllo anti-robot e ha un limite di invii; se ha una domanda <b>allegato</b>, per rispondere serve l’accesso.']],
                    ['titolo' => 'Opzioni: periodo, limite, ricevuta',
                     'passi' => ['<b>Aperto dal / al</b>: il periodo in cui si può rispondere; le date devono esistere davvero. <b>N. massimo di risposte</b>: 0 = nessun limite.', '<b>Una sola risposta per persona</b> (vale per chi ha fatto l’accesso) e <b>Si può modificare la risposta già data</b> (finché il modulo è aperto).', '<b>Email di notifica</b>: indirizzi che ricevono un avviso a ogni risposta. <b>Ricevuta per email</b>: chi ha fatto l’accesso riceve il codice di ricevuta. Dopo l’invio il codice si vede sempre anche sullo schermo.']],
                    ['titolo' => 'Risposte anonime',
                     'passi' => ['Con <b>Risposte anonime</b> il modulo è <b>anonimo per chi lo gestisce</b>: il portale non salva nome ed email accanto alla risposta, e non compaiono nelle risposte, in Excel, in CSV, in PDF né nell’email di notifica.', 'Il portale tiene però una <b>impronta</b>, un codice che non si può trasformare in un nome da chi guarda le risposte: serve solo a evitare che la stessa persona risponda due volte e a farle ritrovare la propria risposta (tessera «I miei form») per correggerla.', 'Nei moduli anonimi la <b>ricevuta non arriva per email</b>, nemmeno a chi ha fatto l’accesso: l’email permetterebbe di capire chi ha risposto. Il codice resta sullo schermo dopo l’invio.'],
                     'nota' => 'È anonimo per chi gestisce il modulo, non in senso assoluto: chi amministra il server potrebbe, con strumenti tecnici, verificare se una persona precisa ha risposto.'],
                    ['titolo' => 'Co-gestori, link e QR code',
                     'passi' => ['Un <b>co-gestore</b> può modificare il modulo, aprirlo, chiuderlo, duplicarlo e leggere le risposte; non può eliminarlo né cambiare i co-gestori (lo fanno il proprietario e gli amministratori). Lo cerchi nell’anagrafe di Ateneo, nella scheda del modulo: deve aver già fatto l’accesso al portale almeno una volta.', '<b>Link e QR da condividere</b> (nella scheda) dà l’indirizzo e il QR code da stampare. In bozza il link dice «Modulo non trovato»; quando il modulo è chiuso o fuori periodo dice il motivo.', 'I moduli aperti compaiono in <b>MyForms · moduli da compilare</b> e nella ricerca del portale solo a chi può compilarli.']],
                    ['titolo' => 'Leggere le risposte ed Excel',
                     'passi' => ['Premi <b>Risposte (N)</b>: tabella con data, profilo, codice di ricevuta e le prime domande; ricerca nel testo e filtri per periodo e profilo. Aprendo una risposta vedi tutte le domande e scarichi gli allegati.', 'Il <b>Riepilogo</b> conta, per le domande a scelta, quante persone hanno scelto ogni opzione, con le percentuali.', '<b>Scarica</b> dà Excel, CSV o PDF di tutte le risposte o solo di quelle filtrate, con una colonna per domanda. Le celle che comincerebbero con = + - @ si scrivono come testo. Gli allegati si scaricano tutti insieme in un ZIP.', 'Puoi eliminare una risposta o tutte (per tutte scrivi il titolo del modulo): si cancellano anche gli allegati e non si torna indietro.']],
                    ['titolo' => 'Chiusura automatica e conservazione',
                     'passi' => ['Il portale chiude da solo il modulo alla data «al» o al numero massimo di risposte e manda al <b>proprietario</b> una email («il modulo si è chiuso: N risposte»), una volta sola per modulo. Se lo riapri a mano non si richiude da solo: cambia anche la scadenza.', 'In <b>Conserva le risposte per (mesi)</b> scegli quanto tenerle; vuoto = mai cancellate. Passato il tempo dall’invio, risposte e allegati si cancellano da soli.', 'Prima il proprietario riceve una email «Tra 7 giorni si cancellano delle risposte»: puoi scaricarle in Excel o aumentare i mesi. Dopo 7 giorni si cancellano solo quelle nominate nell’avviso. Ogni cancellazione resta nel registro delle attività.']],
                ],
            ],
            // La guida per chi fa la richiesta è «pubblicazione»; l’elenco delle colonne qui sotto non si scrive a mano: arriva da ConfigurazioneCampi (intestazioni, «a cura di» e colonne aggiunte comprese)
            'pubblicazioni' => [
                'titolo' => 'Richieste di pubblicazione: per chi le gestisce', 'icona' => 'fa-bullhorn', 'colore' => '#0e7490',
                'a_chi' => 'Per chi lavora le richieste di pubblicazione di docenti e personale e tiene la tabella di monitoraggio (il file Excel), dentro il modulo Amministrazione: ufficio comunicazione e persone abilitate.',
                'in_breve' => 'Le richieste di docenti e personale, una volta approvate, arrivano tra le «Richieste arrivate», nel modulo Amministrazione. Quando una richiesta è pronta la invii al file Excel: da lì completi le colonne di tua competenza (se «Chi compila cosa» è compilato vedi e modifichi solo quelle assegnate a te) e, quando serve, scarichi la tabella in Excel, PDF o CSV. Chi ha tutto il modulo decide anche chi può inviare, chi approva, chi compila cosa, i limiti, i campi e le colonne.',
                'sezioni' => [
                    ['titolo' => 'Dove si trova e chi può entrare',
                     'passi' => ['Le richieste stanno nel modulo <b>Amministrazione</b> del pannello (la sua card è nella pagina iniziale): nel menu a sinistra, <b>«Richieste di pubblicazione»</b>. Gli indirizzi delle email di sempre (<b>pubblicazioni.php?id=…</b>) continuano a funzionare.', 'Entrano gli amministratori e le persone abilitate dall’amministratore in <b>Utenti</b>, tra i «Moduli interi», con una di due voci: <b>«Modulo Amministrazione»</b> apre tutto (richieste, Modulistica, Impostazioni, Campi e colonne); <b>«Amministrazione · Richieste di pubblicazione»</b> apre solo le richieste e la tabella di monitoraggio. Chi ha solo questa seconda voce non vede il resto dell’Amministrazione (né MyForms, che è un modulo a parte).', 'Gli indirizzi indicati nella scheda <b>«Impostazioni»</b> e le persone della lista <b>«Chi lavora»</b> ricevono una email con tutto il testo e il link alla scheda: con l’approvazione accesa quando la richiesta viene <b>approvata</b>, con l’approvazione spenta quando arriva. La lista «Chi lavora» da sola non dà permessi: per aprire la scheda serve l’abilitazione. Chi ha solo le richieste, dalla voce «Impostazioni» della pagina delle richieste, vede la sola parte degli <b>indirizzi</b> e della ricevuta a chi invia; il resto delle impostazioni è per chi ha tutto il modulo (se un indirizzo non è valido non si salva niente).']],
                    ['titolo' => 'Richieste arrivate',
                     'passi' => ['È la scheda che si apre per prima. Contiene le richieste <b>approvate</b> e non ancora nel file Excel, con i numeri in alto: approvate (da guardare), in lavorazione, respinte.', 'Le richieste ancora <b>da approvare</b> stanno sopra, nella sezione chiusa <b>«In attesa di approvazione»</b>, in sola lettura: servono a sapere cosa sta arrivando. Non si possono aprire, inviare al file Excel né eliminare finché chi approva non decide. Quelle <b>respinte da chi approva</b> non compaiono nell’elenco.', 'Per ogni richiesta: <b>«Apri»</b> mostra la scheda, con «Approvata da … il …»; <b>«Invia al file Excel»</b> (chiede conferma) la fa entrare nella tabella di monitoraggio. Se la richiesta è <b>respinta</b> il pulsante non è disponibile e la pagina ne spiega il motivo.', 'Le richieste da guardare compaiono anche nella «Scrivania» del pannello, nel menu a sinistra e, per chi le gestisce, nella tessera <b>«Richieste di pubblicazione»</b> di «Il mio lavoro» nell’area personale. Quelle in attesa di approvazione non contano.']],
                    ['titolo' => 'Invia al file Excel',
                     'passi' => ['La riga entra nella scheda <b>«Tabella di monitoraggio (file Excel)»</b>: solo da questo momento compare nello scaricamento.', 'Il portale precompila <b>D</b> (URL di pubblicazione) e <b>E</b> (altre pagine) con i link scritti dal richiedente, e con <b>«SI»</b> le colonne dei destinatari che il richiedente ha spuntato: <b>L</b> Cittadinanza, <b>P</b> Studenti, <b>Q</b> Docenti, <b>R</b> PTA. Si precompilano solo le colonne ancora vuote.', 'Dopo la pubblicazione correggi D ed E con gli indirizzi veri delle pagine: quello che aveva scritto il richiedente resta visibile accanto, come «scritto dal richiedente».']],
                    ['titolo' => 'Le colonne da completare: cosa contengono e chi le compila',
                     'passi' => self::colonneDaCompletare($cfg_pb),
                     'nota' => '<b>Ognuno modifica solo le sue colonne.</b> Chi gestisce tutto il modulo assegna le colonne alle persone in «Campi e colonne» › «Chi compila cosa»: da quel momento chi ha solo le richieste vede, compila e scarica le colonne assegnate a lui, più i dati di chi invia (in sola lettura) e lo stato, e il portale rifiuta le altre. Amministratori e chi ha tutto il modulo vedono e compilano tutto. Finché non è salvata nessuna casella, tutti gli abilitati modificano tutte le colonne. Il «a cura di» è l’intestazione del file Excel e ogni colonna ha il suo colore. Nomi, «a cura di», colori e posizione delle colonne si cambiano da «Campi e colonne» (chi ha tutto il modulo), dove si possono anche aggiungere colonne nuove; l’elenco qui sopra segue quello che è impostato. Data, richiedente, titolo, sottotitolo, descrizione e modalità sono quelli scritti da chi ha fatto la richiesta e non si cambiano.'],
                    ['titolo' => 'La scheda di una richiesta: dove gli operatori compilano le loro colonne',
                     'passi' => ['In alto una fascia dice se la richiesta è nel file Excel (e dal quando, da chi) o no, con il pulsante giusto: <b>«Invia al file Excel»</b> oppure <b>«Togli dal file Excel»</b>.', 'Sotto, in sola lettura, quello che ha scritto il richiedente: link, destinatari scelti, note, tag, data di inizio pubblicazione, allegati e immagini da scaricare, e anche le risposte ai campi aggiunti dall’amministratore. <b>«Copia il testo»</b> copia titolo, sottotitolo e descrizione senza formattazione, pronti da incollare.', 'Poi le <b>colonne degli operatori</b> che puoi compilare, divise secondo l’«a cura di», e lo <b>stato</b> (Approvata, In lavorazione, Pubblicata, Respinta). Un solo <b>«Salva»</b> salva tutto. Se la riga non è ancora nel file Excel si cambia solo lo stato: le colonne si compilano dopo «Invia al file Excel». Lo stato di una richiesta respinta da chi approva non si cambia.', 'Per completare le richieste una dopo l’altra apri <b>«Da compilare»</b> (nel menu a sinistra, col numero delle righe da completare). Le linguette <b>«Da fare»</b> e <b>«Fatte»</b> dividono le richieste; ogni <b>scheda</b> ha la locandina, i dati essenziali, «N di M compilati» e solo le tue colonne, con l’etichetta Compilato, Da compilare, Da salvare o Da correggere.', 'Ogni scheda ha il suo <b>«Salva»</b> (niente salvataggio automatico): se un campo è sbagliato non si salva niente e l’errore compare accanto al campo. Compilata l’ultima colonna la richiesta passa in «Fatte», da dove la riapri con «Correggi».', 'Chi gestisce tutto il modulo trova in più <b>«Tabella completa»</b>, con tutte le richieste in una tabella sola e le celle vuote evidenziate, e <b>«Solo le mie colonne»</b> (quelle assegnate; senza assegnazioni, quelle col proprio nome in «a cura di»).', 'In fondo trovi chi ha fatto l’ultima modifica e l’elenco delle modifiche (colonna, valore di prima e di dopo).'],
                     'nota' => 'Portare in «Respinta» una riga che è nel file Excel chiede conferma e la toglie dal file.'],
                    ['titolo' => 'Togliere una riga dal file Excel',
                     'passi' => ['Nella scheda premi <b>«Togli dal file Excel»</b> (chiede conferma): la riga esce dalla tabella e dallo scaricamento.', 'Le colonne che avevi compilato <b>restano salvate</b>: se premi di nuovo «Invia al file Excel» quanto hai scritto non viene sovrascritto.']],
                    ['titolo' => 'Righe a mano',
                     'passi' => ['Per le iniziative che non arrivano dalla richiesta online: nella «Tabella di monitoraggio» premi <b>«Nuova riga a mano»</b>.', 'Sono obbligatori data dell’evento, richiedente, titolo e <b>locandina</b> (un file PDF, JPG o PNG); gli altri allegati e le immagini sono facoltativi. La riga entra subito nel file Excel, già approvata.']],
                    ['titolo' => 'Scaricare la tabella',
                     'passi' => ['Nella «Tabella di monitoraggio» filtra per stato, periodo (data dell’evento) o testo e premi <b>«Scarica»</b>: <b>Excel</b>, <b>PDF</b> o <b>CSV</b>. Lo scaricamento rispetta i filtri scelti e contiene solo le righe nel file Excel.', 'Chi vede solo le proprie colonne scarica una <b>copia parziale</b>: i dati di chi invia, lo stato e le colonne assegnate (il nome del file dice «mie_colonne»).', 'Le colonne e le intestazioni sono quelle del file di monitoraggio (o quelle impostate in «Campi e colonne», con le eventuali colonne aggiunte; quelle nascoste non escono), con in più «Sottotitolo iniziativa» (subito dopo il titolo, che si chiama «Titolo iniziativa») e «Stato» in fondo. Date come gg/mm/aaaa, descrizione senza formattazione.', 'Nel CSV i valori che iniziano con = + - @ hanno un apostrofo davanti, perché Excel non li scambi per formule. L’intestazione colorata del file originale non si riproduce.']],
                    ['titolo' => 'Eliminare e conservare',
                     'passi' => ['<b>«Elimina»</b> (chiede conferma) cancella la richiesta e i suoi file e non si può annullare. Una richiesta in attesa di approvazione non si elimina.','Righe e allegati non si cancellano da soli: restano finché qualcuno non li elimina dalla scheda.']],
                    ['titolo' => 'Impostazioni della richiesta (chi ha tutto il modulo)',
                     'passi' => ['In Amministrazione apri la scheda <b>«Impostazioni»</b>: un solo riquadro «Richiesta di pubblicazione», diviso in <b>Chi può inviare</b> (le caselle dei profili: di partenza docenti e personale tecnico amministrativo; non si può aprire a chi non ha fatto l’accesso), <b>Apertura</b> (aperta o chiusa, con il messaggio che vede chi trova la procedura chiusa), <b>Testi</b> (in cima alla pagina, dopo l’invio, le note operative del primo passo e le «Pagine e canali dove pubblicare», che trasformano la domanda sull’indirizzo in una scelta a caselle), <b>Limiti</b> (caratteri del sottotitolo e della descrizione, numero di allegati e di immagini, allegati obbligatori o no, giorni di anticipo della data di inizio pubblicazione) ed <b>Email</b> (indirizzi che ricevono le richieste e ricevuta a chi invia).', 'Un solo <b>«Salva»</b>: se qualcosa non va, i messaggi sono accanto ai campi e non si salva niente. Ogni modifica resta nel registro delle attività, con il valore di prima e di dopo. Le novità valgono subito per la pagina della richiesta e per i controlli del server.'],
                     'nota' => 'Con la procedura chiusa nessuno può inviare, nemmeno chi ha il permesso di gestire le richieste: le richieste già arrivate si lavorano come sempre.'],
                    ['titolo' => 'Chi approva, chi lavora, chi è informato (chi ha tutto il modulo)',
                     'passi' => ['In fondo alle «Impostazioni», tre liste di persone scelte <b>dall’anagrafe di Ateneo</b>: <b>«Chi approva»</b> (riceve la richiesta appena inviata e la approva o la respinge), <b>«Chi lavora»</b> (riceve la richiesta approvata, con il link alla scheda) e <b>«Chi è informato»</b> (riceve solo il riepilogo, senza link).', 'Le scritte in rosso dicono cosa non va: persona uscita dall’anagrafe o senza email, approvatore senza un account collegato (deve entrare una volta nel portale con le credenziali di Ateneo), persona di «Chi lavora» senza l’abilitazione alle richieste.', '<b>«Approvazione accesa»</b> si accende per ultima, con «Salva l’interruttore»: serve almeno un approvatore con un account collegato. Spenta, le richieste nascono già approvate. L’ultimo approvatore non si può togliere finché ci sono richieste in attesa.']],
                    ['titolo' => 'Chi compila cosa (chi ha tutto il modulo)',
                     'passi' => ['In fondo a «Campi e colonne», la griglia <b>colonne × operatori</b>: spunta chi compila ogni colonna; una colonna può avere più persone.', '<b>«Proponi dai nomi “a cura di”»</b> spunta le caselle partendo dai nomi delle intestazioni, senza salvare: controlla e premi <b>«Salva chi compila cosa»</b>.', 'Appena è salvata la prima casella, chi ha solo le richieste vede soltanto le colonne assegnate a lui: conviene riempire la griglia tutta insieme. Le colonne senza nessuno le compila solo chi vede tutto.']],
                    ['titolo' => 'Campi e colonne: cosa si può cambiare e cosa no (chi ha tutto il modulo)',
                     'passi' => ['La scheda <b>«Campi e colonne»</b> ha due parti, ognuna con il suo «Salva». In <b>«Campi del form»</b>, per ogni passo della richiesta, puoi cambiare <b>nome</b>, <b>testo di aiuto</b>, <b>obbligatorio</b>, <b>visibile</b> e l’ordine (su e giù). In <b>«Colonne del file Excel»</b> puoi cambiare <b>intestazione</b>, <b>«a cura di»</b>, <b>colore</b>, <b>visibile</b> e l’ordine; il <b>tipo</b> (testo, SI/NO, numero) solo per le colonne degli operatori.', '<b>Cosa non si cambia:</b> Titolo e Data dell’evento sono sempre visibili e obbligatori; Richiedente e Stato ci sono sempre; le quattro caselle dei destinatari restano un gruppo (se è visibile, ne serve una); allegati e immagini seguono le Impostazioni; il tipo delle colonne scritte da chi fa la richiesta non cambia. La scheda lo dice accanto a ogni campo.', 'Un campo <b>nascosto</b> non si chiede e non si controlla, e nella sua colonna dell’Excel resta vuoto (le richieste già arrivate conservano i loro valori). Un campo reso <b>facoltativo</b> si controlla solo se è compilato. Un passo senza campi visibili la pagina lo salta.', '<b>«Torna all’originale»</b> su ogni riga toglie le tue modifiche a quel campo o a quella colonna; <b>«Torna alle intestazioni originali»</b> lo fa per tutte le intestazioni (chiede conferma). Le originali sono quelle del file «DiBEST_Tabella di monitoraggio.xlsx».'],
                     'nota' => 'Se cambi le intestazioni, il file scaricato non sarà più uguale alla Tabella di monitoraggio originale. Ogni modifica resta nel registro delle attività.'],
                    ['titolo' => 'Campi e colonne nuovi (chi ha tutto il modulo)',
                     'passi' => ['Sempre in «Campi e colonne»: <b>«Campi aggiunti»</b> crea un campo nuovo del form con lo stesso costruttore di MyForms (testo, testo lungo, scelta singola, caselle, data, numero, sì/no, link; niente file). Scegli il <b>passo</b> in cui compare (in fondo al passo), se è obbligatorio, il testo di aiuto e se <b>diventa una colonna del file Excel</b>, con la sua intestazione: la colonna esce dopo quella dell’ultimo campo del suo passo. Il valore scritto compare nella scheda della richiesta, nelle email e, se c’è la colonna, nel file.', '<b>«Colonne aggiunte»</b> crea una colonna nuova per gli operatori: intestazione, «a cura di», colore, tipo (testo, SI/NO, numero) e dopo quale colonna sta. Si compila nella scheda della richiesta come le altre e le modifiche finiscono nel registro. Conta come «da completare» solo se è visibile.', '<b>Eliminare:</b> un campo o una colonna che non ha valori in nessuna richiesta si elimina; se ne ha, puoi solo <b>nasconderlo</b> (i valori restano e tornano se lo riaccendi) e la scheda dice in quante richieste ci sono valori. Il tipo di un campo che ha già risposte non si cambia.'],
                     'nota' => 'I nomi interni dei campi e delle colonne nuovi non si riusano mai: anche dopo un’eliminazione, un campo nuovo è sempre nuovo.'],
                ],
            ],
            'approvazione' => [
                'titolo' => 'Richieste di pubblicazione: per chi le approva', 'icona' => 'fa-stamp', 'colore' => '#9f1239',
                'a_chi' => 'Per il Direttore e per le persone che approvano le richieste di pubblicazione prima che arrivino all’ufficio comunicazione.',
                'in_breve' => 'Quando un docente o il personale chiede di pubblicare un’iniziativa ricevi una email: apri, leggi il riepilogo e i file e premi «Approva» oppure «Respingi» con il motivo. Basta che decida una sola persona. Non serve il pannello di gestione.',
                'sezioni' => [
                    ['titolo' => 'Chi può approvare',
                     'passi' => ['Le persone della lista <b>«Chi approva»</b>, scelte dall’anagrafe di Ateneo da chi gestisce il modulo Amministrazione.', 'Il permesso vale per il tuo account del portale: entra <b>almeno una volta con le credenziali di Ateneo</b>, così il portale ti riconosce.'],
                     'nota' => 'Se l’approvazione è spenta nelle impostazioni, le richieste nascono già approvate e a chi approva non arriva niente.'],
                    ['titolo' => 'Quando arriva una richiesta',
                     'passi' => ['Ricevi una email con il riepilogo e il pulsante <b>«Apri e approva»</b>; se non sei collegato, prima fai l’accesso e poi torni alla richiesta.', 'Nell’<b>Area personale</b> la tessera <b>«Richieste di pubblicazione da approvare»</b> (anche in «Il mio lavoro») mostra quante aspettano.', 'La pagina ha due elenchi: <b>«Da approvare»</b> e <b>«Decise di recente»</b>.']],
                    ['titolo' => 'Approvare o respingere',
                     'passi' => ['Premi <b>«Apri e decidi»</b>: leggi tutto quello che ha scritto chi chiede e scarica la locandina e gli altri file.', '<b>«Approva»</b> (chiede conferma): la richiesta passa all’ufficio comunicazione e chi l’ha inviata riceve la notizia.', '<b>«Respingi»</b> apre il campo del <b>motivo</b>, obbligatorio: scrivilo per chi ha chiesto, perché lo legge nell’email e in «Le mie richieste». Poi premi «Respingi con questo motivo».'],
                     'nota' => 'La decisione non si annulla dal portale: se hai sbagliato, chi ha chiesto la pubblicazione può inviare una richiesta nuova.'],
                    ['titolo' => 'Basta una persona sola',
                     'passi' => ['Vale la <b>prima</b> decisione. Le altre persone che approvano ricevono una email che dice chi ha deciso e quando.', 'Se apri una richiesta già decisa leggi «Questa richiesta è già stata approvata (o respinta) da … il …»: non devi fare niente. Se la decidi nello stesso momento di un altro, il portale tiene la prima e te lo dice.']],
                    ['titolo' => 'Che cosa succede dopo',
                     'passi' => ['Approvata: la ricevono l’ufficio comunicazione (lista «Chi lavora» e indirizzi delle impostazioni) e, per conoscenza, le persone della lista «Chi è informato», senza link al pannello.', 'Respinta: la sa chi l’ha inviata, con il motivo, e le altre persone che approvano.', 'Ognuno riceve una email sola per ogni richiesta, anche se sta in più liste.']],
                ],
            ],
            // SOS aule: la pagina è pubblica, quindi il numero di riserva non si scrive qui (sta sul cartello dell'aula e in sos.php)
            'sos' => [
                'titolo' => 'Docenti: SOS aula, chiedere aiuto', 'icona' => 'fa-life-ring', 'colore' => '#b91c1c',
                'a_chi' => 'Per chi fa lezione e ha un problema in aula: proiettore, computer, audio, rete, porta chiusa, materiale che manca.',
                'in_breve' => 'Inquadri il QR del cartello in aula, entri con le credenziali di Ateneo, scegli il problema e invii. La richiesta arriva subito a chi segue quell’aula; sul telefono vedi a che punto è.',
                'sezioni' => [
                    ['titolo' => 'Come si segnala',
                     'passi' => ['Inquadra il <b>QR</b> sul cartello dell’aula e accedi con le credenziali di Ateneo. Senza cartello: nell’Area personale premi «Le mie segnalazioni SOS» e scegli l’aula dall’elenco.', 'Controlla l’aula: con il QR è già scelta; se non è quella premi «Cambia».', 'Tocca il <b>tipo di problema</b> e di’ <b>quanto è urgente</b> («La lezione è ferma», se non puoi andare avanti).', 'Descrivi il problema (con «Altro» è obbligatorio). Se serve aggiungi una foto e il numero a cui richiamarti.', 'Premi <b>«Invia la richiesta di aiuto»</b>. Se per quell’aula c’è già una segnalazione aperta puoi aggiungere una nota a quella, oppure scegliere «Invia comunque».'],
                     'nota' => 'Può inviare chi ha un profilo ammesso dal Dipartimento (di partenza docenti e personale).'],
                    ['titolo' => 'Cosa succede dopo',
                     'passi' => ['Chi segue l’aula riceve l’avviso, e interviene di persona o manda uno studente. La pagina della segnalazione si aggiorna da sola e dice chi se ne occupa.', 'Finché è aperta puoi <b>aggiungere una nota</b>; se hai risolto per conto tuo premi <b>«Annulla, ho risolto da solo»</b>, così nessuno viene per niente.', 'Alla chiusura ricevi una email con l’esito.', 'Se è segnata come risolta ma il problema c’è ancora, entro 24 ore premi <b>«Non è risolto»</b>: torna a chi segue l’aula.', 'Le tue segnalazioni restano in «Le mie segnalazioni», sotto il modulo e nell’Area personale.']],
                    ['titolo' => 'Se il telefono non prende: il telefono di riserva',
                     'passi' => ['Sul cartello dell’aula c’è il <b>numero di riserva</b>: chiamalo se il telefono non ha rete, se non riesci ad accedere o se la pagina dice che il servizio non è attivo.', 'Fuori dagli orari di presidio puoi inviare lo stesso: la pagina ti avvisa che potrebbe non intervenire nessuno subito.']],
                ],
            ],
            'sos_referente' => [
                'titolo' => 'SOS aule: referente dell’aula', 'icona' => 'fa-screwdriver-wrench', 'colore' => '#b91c1c',
                'a_chi' => 'Per il personale tecnico amministrativo indicato come referente di una o più aule, e per i responsabili di riserva.',
                'in_breve' => 'Ricevi email e notifica quando un docente segnala un problema in una tua aula. Dalla pagina «SOS aule» la prendi tu, mandi uno studente, la inoltri a un altro ufficio o la chiudi. I responsabili di riserva vedono tutte le aule.',
                'sezioni' => [
                    ['titolo' => 'Prima di cominciare',
                     'passi' => ['Entra nel portale almeno una volta con le credenziali di Ateneo: gli avvisi arrivano anche prima, ma per agire serve il tuo account.', 'Nell’Area personale, «Il mio lavoro», apri la tessera <b>«SOS aule»</b> (o il pulsante «Apri» nell’email).', 'Dal telefono premi <b>«Attiva le notifiche su questo telefono»</b>. Su iPhone aggiungi prima il sito alla schermata Home.']],
                    ['titolo' => 'Prendere in mano una segnalazione',
                     'passi' => ['Le schede sono «Da fare», «In corso» e «Chiuse»; le lezioni ferme stanno in cima.', '<b>«Ci penso io»</b> se intervieni tu; <b>«Mando uno studente»</b> per affidarla a uno studente part-time in servizio oggi.', 'Con <b>«Chiama»</b> telefoni al docente, se ha lasciato il numero.', 'Se un collega è arrivato prima, la pagina dice chi l’ha presa e a che ora.']],
                    ['titolo' => 'Chiuderla',
                     'passi' => ['<b>«Risolta»</b>: il docente riceve l’esito per email.', '<b>«La inoltro a…»</b>: scrivi a quale ufficio e quando lo hai avvisato; resta aperta finché non la chiudi.', '<b>«Chiudo senza soluzione»</b>: scrivi il perché.', 'Se lo studente segna «Non risolto», o il docente dice «Non è risolto», torna a te: riprendila, passala a un altro studente, inoltrala o chiudila.'],
                     'nota' => 'Se una segnalazione resta «In attesa» troppo a lungo parte un promemoria ai referenti dell’aula e ai responsabili di riserva.'],
                ],
            ],
            'sos_studente' => [
                'titolo' => 'SOS aule: studente part-time', 'icona' => 'fa-person-walking', 'colore' => '#b91c1c',
                'a_chi' => 'Per gli studenti con la collaborazione part-time che intervengono nelle aule.',
                'in_breve' => 'Quando un referente ti affida un intervento ricevi email e notifica. Dici che stai andando, poi segni se hai risolto o no. Vedi solo le segnalazioni affidate a te.',
                'sezioni' => [
                    ['titolo' => 'Entrare',
                     'passi' => ['Il Dipartimento ti inserisce con la tua email <code>@studenti.unical.it</code> e il periodo della collaborazione: accedi al portale con quella.', 'Nell’Area personale, «Il mio lavoro», apri la tessera <b>«SOS aule»</b>.', 'Premi <b>«Attiva le notifiche su questo telefono»</b>. Su iPhone aggiungi prima il sito alla schermata Home.']],
                    ['titolo' => 'L’intervento',
                     'passi' => ['Leggi aula, problema e urgenza; con <b>«Chiama»</b> telefoni al docente, se ha lasciato il numero.', 'Premi <b>«Sto andando»</b>: il docente vede che stai arrivando.', 'A lavoro finito premi <b>«Risolto»</b> e conferma.', 'Se non ci sei riuscito premi <b>«Non risolto»</b>, scegli che cosa non ha funzionato e invia: la segnalazione torna al referente.', 'Puoi segnare i <b>minuti</b> dell’intervento (facoltativo).'],
                     'nota' => 'Se ricevi «non serve più che tu vada», il referente l’ha ripresa, passata a un altro o risolta.'],
                ],
            ],
            'sos_gestione' => [
                'titolo' => 'Amministrazione: preparare SOS aule', 'icona' => 'fa-gear', 'colore' => '#0e7490',
                'a_chi' => 'Per gli amministratori e chi ha tutto il modulo Amministrazione: aule, persone, cartelli e accensione del modulo.',
                'in_breve' => 'Il modulo nasce <b>spento</b>. Nel pannello, Amministrazione › SOS aule, prepari nell’ordine aule, persone, modulo e impostazioni; poi stampi i cartelli e lo accendi.',
                'sezioni' => [
                    ['titolo' => 'Le aule',
                     'passi' => ['Scheda <b>«Aule»</b>: per ogni aula scrivi nome (per esempio 5C2) ed edificio. Ognuna ha il suo QR.', 'Un’aula con segnalazioni non si cancella: si spegne.', '«Rigenera il QR» solo se serve davvero: il cartello già stampato smette di valere.']],
                    ['titolo' => 'Le persone',
                     'passi' => ['Scheda <b>«Persone»</b>: per ogni aula aggiungi i referenti cercandoli in anagrafe, poi i responsabili di riserva.', 'Aggiungi gli studenti part-time con l’email di Ateneo e il periodo dal/al.', 'Leggi gli avvisi in rosso: dicono chi non riceve niente o non è ancora entrato nel portale.']],
                    ['titolo' => 'Modulo e impostazioni',
                     'passi' => ['Scheda <b>«Modulo»</b>: etichette dei campi, campi aggiunti, tipi di problema ed esiti «non risolto», con l’anteprima.', 'Scheda <b>«Impostazioni»</b>: chi può inviare, telefono di riserva, orari di presidio, minuti dei promemoria, testo introduttivo, giorni di conservazione delle foto.', 'Il promemoria parte al primo giro del cron dopo i minuti scelti: può arrivare fino a 15 minuti dopo.']],
                    ['titolo' => 'Cartelli e accensione',
                     'passi' => ['Compila prima il telefono di riserva: è scritto sul cartello.', 'Scheda «Aule»: <b>«Stampa i cartelli di tutte le aule»</b> (un foglio per aula) e appendili.', 'In «Impostazioni» accendi <b>«Aperto: si possono inviare segnalazioni»</b>. Non si accende se nessuno riceverebbe le segnalazioni.', 'Con il modulo acceso usa «Prova il QR» e controlla che l’aula sia quella giusta.', 'La scheda <b>«Registro»</b> ha tutte le segnalazioni, i numeri del periodo, le aule con problemi ripetuti, i minuti degli studenti e gli scarichi.']],
                ],
            ],
            'amministrazione' => [
                'titolo' => 'Amministrazione: modulistica e procedure online', 'icona' => 'fa-building-columns', 'colore' => '#0e7490',
                'a_chi' => 'Per chi ha il modulo Amministrazione nel pannello: la modulistica amministrativa del personale e le procedure online, a cominciare dalla richiesta di pubblicazione.',
                'in_breve' => 'Il modulo Amministrazione raccoglie le cose amministrative del Dipartimento: i documenti e i link della «Modulistica amministrativa», le procedure online (per ora la richiesta di pubblicazione di un’iniziativa su sito e social) e le impostazioni per gestirle da soli, senza toccare il codice.',
                'sezioni' => [
                    ['titolo' => 'Cos’è e come si apre',
                     'passi' => ['Nel pannello la card <b>«Amministrazione»</b> apre il modulo. Il menu a sinistra ha <b>«Cosa devo fare»</b> (le richieste da guardare e quelle da completare, con i pulsanti che ti portano alla cosa giusta) e <b>«Richieste di pubblicazione»</b>; chi ha tutto il modulo trova anche <b>«Modulistica»</b>, <b>«Impostazioni»</b> e <b>«Campi e colonne»</b>.', 'Le richieste da guardare compaiono anche nella «Scrivania» del pannello e, per chi le gestisce, nella tessera «Il mio lavoro» dell’area personale.']],
                    ['titolo' => 'Chi abilita cosa',
                     'passi' => ['Gli amministratori entrano sempre. Per gli altri decide l’amministratore, in <b>Utenti</b>, tra i «Moduli interi»: <b>«Modulo Amministrazione»</b> apre tutto il modulo; <b>«Amministrazione · Richieste di pubblicazione»</b> apre solo le richieste e la tabella di monitoraggio (è la voce che c’era già: chi la aveva continua a lavorare come prima).', 'Chi ha solo le richieste non vede la Modulistica, le Impostazioni e «Campi e colonne». Chi ha tutto il modulo le vede e può anche lavorare le richieste.', 'Chi può <b>inviare</b> una richiesta di pubblicazione è un’altra cosa: non serve nessun permesso del pannello, basta avere uno dei profili scelti nelle Impostazioni (di partenza docenti e personale tecnico amministrativo).']],
                    ['titolo' => 'La Modulistica amministrativa',
                     'passi' => ['La scheda <b>«Modulistica»</b> (solo per chi ha tutto il modulo) ha in cima le <b>procedure online</b> e sotto i <b>documenti da scaricare</b> e i <b>link</b>, divisi per categoria (per esempio Missioni, Acquisti, Personale). Per ogni voce scrivi il titolo, la categoria, la descrizione con le istruzioni, carichi il file o indichi il link, e scegli se è <b>pubblicata</b> (visibile nella pagina pubblica); con «Elimina» (in fondo e in rosso) la togli.', 'I documenti si caricano come quelli della Didattica. I moduli online che aprono una pratica (missioni, rimborsi…) arriveranno più avanti: oggi qui ci sono solo documenti e link.', 'Il pubblico li trova nella pagina <b>«Modulistica amministrativa»</b>, con la ricerca e le categorie. La pagina e la «Richiesta di pubblicazione di un’iniziativa» non compaiono da sole nel menu del sito: le mette l’amministratore dal pannello, voce <b>Menu</b>.'],
                     'nota' => 'La modulistica della Didattica è un’altra pagina e non cambia: i documenti dell’Amministrazione non compaiono lì, e viceversa.'],
                    ['titolo' => 'Le procedure online: la richiesta di pubblicazione',
                     'passi' => ['In cima alla scheda «Modulistica» la carta della <b>Richiesta di pubblicazione</b> dice se la procedura è <b>aperta o chiusa</b>, <b>chi può inviarla</b> e ha i collegamenti alla pagina pubblica, alle richieste e alle impostazioni.', 'Nelle <b>Impostazioni</b> decidi chi può inviare, apri o chiudi la procedura (con il messaggio per chi la trova chiusa), cambi i testi, i limiti e gli indirizzi che ricevono le richieste. In <b>«Campi e colonne»</b> cambi i campi della richiesta e le colonne del file Excel e ne aggiungi di nuovi.', 'Come si lavorano le richieste e come si compilano le colonne è nella guida <b>«Richieste di pubblicazione: per chi le gestisce»</b>; come si fa una richiesta, nella guida <b>«Docenti e personale: chiedere la pubblicazione di un’iniziativa»</b>.']],
                ],
            ],
            'amministratore' => [
                'titolo' => 'Amministratore e Ufficio didattico', 'icona' => 'fa-gear', 'colore' => '#475569',
                'a_chi' => 'Per chi configura il portale: moduli e iter, uffici e persone, utenti, backup.',
                'in_breve' => 'La «Scrivania» mostra ciò che aspetta te. I moduli delle pratiche si creano e si modificano dal pannello, senza toccare il codice; gli uffici decidono chi lavora ogni passo; il backup gira da solo e si può provare a ripristinare.',
                'sezioni' => [
                    ['titolo' => 'La scrivania', 'immagine' => 'adm_scrivania.png', 'didascalia' => 'Le cose da fare e i moduli a cui hai accesso.',
                     'passi' => ['Dopo l’accesso al pannello trovi «Cose da fare»: pratiche da assegnare, verbali da firmare, convenzioni, tutorato.', 'I moduli (Eventi, Formazione Scuola Lavoro, Didattica, MyForms, Amministrazione, Persone e permessi, Sito pubblico, Sistema) si aprono dalle card: vedi solo quelli per cui sei abilitato.']],
                    ['titolo' => 'Come è fatto il pannello: «Cosa devo fare», «Altro» e «Scarica»', 'immagine' => 'adm_did_home.png', 'didascalia' => 'La prima schermata della Didattica: i numeri di quello che aspetta te, e sotto tutte le sezioni.',
                     'passi' => ['Ogni area del pannello si apre su <b>«Cosa devo fare»</b>: poche schede con un numero e un pulsante. Le schede <b>rosse</b> aspettano te, quelle <b>gialle</b> aspettano qualcun altro (non devi fare altro), quelle con <b>0</b> sono a posto.', 'Il pulsante grande di una scheda ti porta direttamente alla cosa da fare. Sotto le schede trovi l’elenco di <b>tutte le sezioni</b>, con una riga che dice a cosa servono (in Didattica anche <b>Tirocini</b>).', 'Le azioni che servono di rado (modificare, duplicare, archiviare, eliminare, stampare, scrivere a tutti) sono nel menu <b>«Altro»</b>. Il pulsante «Elimina» è sempre in fondo e in rosso.', 'Ogni elenco si scarica dal menu <b>«Scarica»</b> in <b>Excel, PDF o CSV</b>. Se hai spuntato alcune righe o filtrato l’elenco, il file contiene solo quelle.'],
                     'nota' => 'Il menu a sinistra non cambia: le voci sono sempre le stesse. «Cosa devo fare» è la prima voce di ogni modulo.'],
                    ['titolo' => 'Didattica: le pratiche e le sedute', 'immagine' => 'adm_did_pratica.png', 'didascalia' => 'Una pratica: in alto cosa fare adesso, poi l’iter. L’assegnazione a un’altra persona è in un riquadro che si apre solo quando serve.',
                     'passi' => ['Da «Cosa devo fare» apri le <b>pratiche da lavorare</b> o <b>da assegnare</b>: ogni pratica dice in alto <b>cosa fare adesso</b> e ha un solo pulsante per farlo.', 'Per passare la pratica a un’altra persona apri il riquadro «Passa la pratica a un’altra persona»: sceglie il passo, l’operatore e, se vuoi, una nota interna.', 'Una <b>seduta</b> ha sette passi (convocazione, presenze, cosa è stato detto, pratiche e decisioni, esiti agli studenti, verbale, firme): in alto vedi il <b>passo corrente</b> con il pulsante «Vai al passo».', 'Dalla seduta, «Scarica» dà il verbale in Word e l’elenco delle pratiche in Excel, PDF o CSV.']],
                    ['titolo' => 'Tutorato: le lettere di incarico', 'immagine' => 'adm_tutorato.png', 'didascalia' => 'Tutorato: lettere da inviare, da firmare, da protocollare e pagamenti.',
                     'passi' => ['«Cosa devo fare» mostra le lettere per punto dell’iter: <b>da inviare</b>, <b>aspettano lo studente</b>, <b>da firmare</b>, <b>da protocollare</b>, <b>da validare e pagare</b>.', 'Il percorso è lo stesso per tutti i bandi: vincitore, lettera, conferma dello studente con SPID/CIE, firma del docente, firma del Direttore, protocollo, registro e fine attività, UNILAV e pagamento.', 'Con l’<b>iter per Uniticket</b> in più c’è la presa di servizio da verificare prima di inviare la lettera, e a firme finite lettera e modello SCAFIS da allegare su Uniticket; poi il percorso è identico.']],
                    ['titolo' => 'Formazione Scuola Lavoro: scuole e convenzioni',
                     'passi' => ['Apri «Scuole e convenzioni»: ogni scuola è una riga, e in cima ci sono le <b>cose da fare</b> (da controllare, dal Direttore, da protocollare, da registrare, messaggi da leggere, scuole senza convenzione…): premi una tessera per vedere solo quelle scuole.', 'Apri la scheda di una scuola: in testata un solo pulsante dice <b>cosa fare adesso</b> («Controlla la convenzione», «Manda al Direttore», «Protocolla e registra», «Avvia la stipula», «Rinnova») e porta al riquadro giusto. Sotto vedi i passi (la scuola compila, tu protocolli, il Direttore firma, tu registri, fatto), i documenti, gli eventi di tutte le sedi e i docenti referenti.', 'Il <b>registro</b> mostra l’originale e il documento protocollato, con la data e da dove vengono, l’Allegato A e le integrazioni; «Scrivi alla scuola» manda una email ai docenti che scegli.', 'Nel menu «Altro» della scheda: modificare, eliminare, registrare una convenzione già firmata fuori dal portale. «Numeri e report» (per chi gestisce tutta la FSL) ha il riepilogo dell’anno scolastico, le valutazioni e il report per il Ministero, con le tabelle in Excel, PDF e CSV.']],
                    ['titolo' => 'Eventi, iscritti e statistiche', 'immagine' => 'adm_ev_dashboard.png', 'didascalia' => 'La dashboard di un’area: iscrizioni da approvare, messaggi, attestati da controllare e turni in arrivo.',
                     'passi' => ['Nella dashboard dell’area le schede in alto dicono cosa fare: <b>iscrizioni da approvare</b>, <b>messaggi da leggere</b>, <b>attestati da controllare</b>, <b>turni dei prossimi 7 giorni</b>.', 'In «Eventi e turni» ogni evento ha il pulsante <b>Modifica</b> e il menu <b>Altro</b> (scheda pubblica, duplica, archivia, elimina); anche ogni turno ha Modifica e un menu (QR dell’aula, duplica, elimina). Le «Sezioni» per raggruppare gli eventi sono in un riquadro che si apre solo se serve.', 'In «Iscritti e presenze» ogni riga ha un pulsante principale (<b>Approva</b> se la richiesta aspetta te, altrimenti <b>Apri</b>) e un menu con ricevuta, messaggi, attestato, annulla ed elimina. In alto: «Aggiungi un iscritto», «Scanner», «Altro» (scrivi a tutti, badge, attestati) e «Scarica».']],
                    ['titolo' => 'Persone e permessi e Sistema', 'immagine' => 'adm_portale_home.png', 'didascalia' => 'Persone e permessi e Sistema: i controlli da guardare e tutte le sezioni.',
                     'passi' => ['La prima schermata mostra: <b>controlli del sito</b> da guardare, <b>email non partite</b> nell’ultima settimana, <b>persone non più in anagrafe</b> e <b>Direttore da indicare</b>.', 'In «Sistema» le impostazioni di invio (SMTP) sono in un riquadro chiuso: si aprono solo se cambia il server di posta.']],
                    ['titolo' => 'Moduli e iter delle pratiche', 'immagine' => 'adm_moduli.png', 'didascalia' => 'Moduli e documenti: le pratiche attive, i campi e l’iter di ciascuna.',
                     'passi' => ['In Didattica, «Moduli e documenti»: ogni pratica nasce inattiva. Aprila con «Anteprima», controlla campi e testi e attivala quando va bene.', 'Dalla procedura guidata a sette passi cambi campi, iter (chi la lavora e in che ordine), testo del verbale ed email. Con «Copia» parti da una pratica simile.', 'Gli uffici e le persone si indicano in «Ufficio e ricevimento»: l’ufficio protocollo, quelli dei corsi di studio, Internazionalizzazione, Ufficio attestati.', 'I certificati sono una sola pratica con tendina (iscrizione, laurea, rinuncia); la tesi unisce richiesta, Conservazione e Restauro e variazione.']],
                    ['titolo' => 'Il mio lavoro nell’area personale', 'passi' => ['Dopo l’accesso, nell’<b>area personale</b> trovi la scheda <b>«Il mio lavoro»</b>: una tessera per ogni cosa che gestisci (pratiche degli studenti, protocollo, sedute e verbali, convenzioni, tutorato, assistenza, richieste di pubblicazione), con il <b>numero delle cose che aspettano</b>.', 'I pulsanti sotto la tessera sono <b>tutte le azioni</b> che puoi fare e aprono subito la vista giusta (per esempio «Da assegnare», «Assegnate a me», «Nuova seduta»). Se gestisci un’area, la sua tessera ha <b>iscritti e presenze, scanner, messaggi, sondaggi, statistiche</b> e, se puoi, «Nuovo evento» e «Nuovo progetto». Si lavora nella stessa pagina di sempre, con gli stessi permessi; in alto c’è il pulsante <b>Area personale</b> per tornare.', 'La scheda compare solo a chi ha almeno una cosa da gestire. In Sito pubblico → <b>Area personale (riquadri)</b> puoi spostarla, spegnerla o limitarla a un profilo.']],
                    ['titolo' => 'Riepilogo settimanale con l’agenda', 'passi' => ['In Sistema → <b>Sistema e registri</b> (scheda <b>Email e promemoria</b>) trovi «Riepilogo settimanale con l’agenda», <b>spento</b> di partenza: lo accendi tu con un pulsante (e lo spegni quando vuoi).', 'Da acceso, l’email settimanale «Da fare per te» porta anche gli appuntamenti dei sette giorni a venire (eventi, aule, ricevimenti, scadenze) e arriva anche a chi ha solo qualcosa in agenda, studenti compresi, con il testo «La tua settimana». Ognuno può disiscriversi dal link in fondo; i testi si cambiano in «Email».'],
                     'nota' => 'Non cambia i promemoria al Direttore e agli uffici: quelli si sospendono dalla scheda «Promemoria al Direttore e agli uffici».'],
                    ['titolo' => 'Uffici e persone', 'passi' => ['In Persone e permessi → <b>Uffici e persone</b> crei gli uffici del Dipartimento (Direzione, protocollo, uffici dei corsi di studio, segreteria…) e di Ateneo (pagamenti…): una volta sola, poi si richiamano ovunque.', 'Le persone si scelgono <b>sempre dall’anagrafe di Ateneo</b> (non c’è l’inserimento a mano). Una persona può stare in più uffici.', 'Per gli uffici che lavorano le pratiche indichi anche i <b>compiti</b> (pratiche, sedute, ricevimento, bandi) e i corsi di studio seguiti: senza compiti la persona è nell’ufficio e riceve gli avvisi, ma non apre il pannello Didattica.', 'La <b>Direzione</b> (Direttore e vice direttore) e la segreteria di direzione sono uffici fissi: da lì si imposta chi firma e si attiva «Direttore assente».', 'Gli stessi uffici si scelgono nell’iter dei moduli, nel bando di tutorato (ufficio che paga), tra i responsabili di una risorsa e per le convenzioni FSL (ufficio convenzioni).'],
                     'nota' => 'Un ufficio che è nell’iter di un modulo, ha pratiche in corso, paga un bando o è responsabile di una risorsa non si può eliminare: il portale dice dove è usato.'],
                    ['titolo' => 'Cambiare il testo di un’email', 'passi' => ['In Sistema → <b>Testi delle email</b> trovi <b>tutte</b> le email che il portale invia, divise per modulo (Didattica, Tutorato, Convenzioni, Risorse, Eventi e iscrizioni, Direzione e sistema). I moduli sono <b>schede</b> in alto (Tutorato, Didattica, Convenzioni, Risorse, Eventi e iscrizioni, Direzione e sistema): la scheda in cui eri resta aperta quando torni dall’editor. Per ogni email c’è scritto <b>quando parte</b> e <b>a chi arriva</b>; la ricerca in alto cerca in tutti i moduli. Dalle pagine dei moduli il pulsante «Testi delle email» apre l’elenco già limitato a quel modulo.', 'Apri un’email: cambi l’oggetto, il testo e (se c’è) la scritta del pulsante. I dati che cambiano da persona a persona (nome, bando, date…) si inseriscono con i <b>segnaposto</b> tra doppie graffe, per esempio <code>{{tutor}}</code>: clicca il segnaposto a destra per inserirlo dove si trova il cursore. Il testo si scrive semplice: una riga vuota separa i paragrafi, <code>**così**</code> è il grassetto, le righe che iniziano con <code>- </code> sono un elenco, quelle con <code>&gt; </code> una citazione evidenziata. Le email degli eventi si scrivono con l’editor e usano segnaposto a graffa singola, come <code>{NOME}</code>.', '<b>Anteprima</b> mostra l’email con dati d’esempio senza salvare; <b>Inviami una prova</b> la manda al tuo indirizzo; <b>Salva</b> la rende valida da subito; <b>Ripristina l’originale</b> torna al testo scritto dal portale. Ogni modifica resta nel registro attività con chi l’ha fatta.', 'Alcune email degli eventi (attestato, sondaggio) sono <b>facoltative</b>: hanno la spunta «Invia questa email» e senza la spunta non partono.'],
                     'nota' => 'Chi gestisce un modulo (Didattica, tutorato, convenzioni) cambia le email del proprio modulo; le altre le cambiano gli amministratori. Il link del pulsante e le parti preparate dal portale (tabelle, elenchi) non si modificano da qui.'],
                    ['titolo' => 'Prenotazioni e risorse', 'immagine' => 'adm_prenotazioni.png', 'didascalia' => 'Le prenotazioni dell’area, con gli stati e i filtri.',
                     'passi' => ['Ogni risorsa ha orari, durata dello slot, approvazione sì/no e, se vuoi, la ripetizione (settimanale, ogni due settimane, mensile).', 'Le liste d’attesa funzionano da sole: non c’è nulla da configurare. Il responsabile e il Direttore vedono le richieste ferme.']],
                    ['titolo' => 'Backup e ripristino', 'immagine' => 'adm_sistema.png', 'didascalia' => 'Sistema: email, backup e controlli notturni.',
                     'passi' => ['Ogni notte il portale esporta il database, comprime i file del sito (comprese le cartelle uploads con verbali, convenzioni e allegati) e li copia sul NAS. Una copia cifrata del solo database arriva per email agli indirizzi indicati.', 'Dopo ogni backup viene <b>verificato</b>: il file del database si rilegge per intero e lo ZIP dei file si riapre. Se qualcosa non torna ricevi un’email e lo vedi in «Sistema».', 'Una volta al mese conviene <b>provare il ripristino</b> (non tocca il portale): <code>php strumenti/ripristina_backup.php prova backup_DB_…sql.gz</code> importa il database in un database di prova e confronta tabelle e righe.', 'Per i file: <code>php strumenti/ripristina_backup.php file backup_SITO_…zip cartella_nuova</code> li estrae in una cartella a parte, da cui si copiano quelli che servono.', 'Il <b>ripristino vero</b> del database cancella e ricrea le tabelle: <code>… database backup_DB_…sql.gz --sovrascrivi-il-database-del-portale</code>. Si usa solo dopo aver provato il backup; poi si svuota la cartella cache e si apre il portale.'],
                     'nota' => 'Il backup completo dipende dalle variabili nel file .env: BACKUP_NAS_PATH (cartella del NAS), BACKUP_EMAIL e BACKUP_PASSWORD (almeno 12 caratteri) per la copia cifrata del database.'],
                ],
            ],
        ];
    }

    /**
     * Le impostazioni e la configurazione dei campi della richiesta di pubblicazione. Se il contenitore non è avviato (prove senza database) o la lettura
     * fallisce valgono i valori di partenza: la guida non deve mai impedire di aprire una pagina.
     *
     * @return array{0: array<string, mixed>, 1: ConfigurazioneCampi}
     */
    private static function configurazionePubblicazioni(): array
    {
        try {
            return [App::get(ImpostazioniPubblicazioni::class)->tutte(), App::get(ConfigurazioneCampi::class)];
        } catch (Throwable $e) {
            return [ImpostazioniPubblicazioni::INIZIALI, ConfigurazioneCampi::predefinita()];
        }
    }

    /** Un nome scritto dall'amministratore dentro un testo della guida: senza i segni che la pagina leggerebbe come marcatori. */
    private static function pulito(string $testo): string
    {
        return trim(str_replace(['<', '>'], '', $testo));
    }

    private static function numeroInParole(int $n): string
    {
        return [1 => 'un solo', 2 => 'due', 3 => 'tre', 4 => 'quattro', 5 => 'cinque', 6 => 'sei', 7 => 'sette'][$n] ?? (string) $n;
    }

    /**
     * I passi della richiesta come li vede chi la compila: solo quelli che hanno campi visibili (il primo e il riepilogo ci sono sempre), con i campi
     * di ognuno, i limiti delle impostazioni e i campi aggiunti dall'amministratore.
     *
     * @param array<string, mixed> $imp ImpostazioniPubblicazioni::tutte()
     * @return list<string>
     */
    private static function passiDellaRichiesta(array $imp, ConfigurazioneCampi $cfg): array
    {
        $ultimo = array_key_last(PassiRichiesta::PASSI);
        $righe = [];
        $n = 0;
        foreach ($cfg->passiVisibili() as $passo) {
            $n++;
            $titolo = PassiRichiesta::PASSI[$passo];
            $testo = match (true) {
                $passo === 1 => 'Leggi le note operative (le scrive l’amministratore: la richiesta si fa solo da qui, le immagini devono essere .jpg o .png, i PDF vengono pubblicati come «Locandina_titolo_breve»). Spunta <b>«Ho letto»</b> per proseguire.',
                $passo === $ultimo => 'Rileggi tutto: accanto a ogni sezione <b>«Modifica»</b> ti riporta al passo giusto. Quando va bene premi <b>«Invia la richiesta»</b>.',
                default => self::campiDelPasso($passo, $imp, $cfg),
            };
            $righe[] = '<b>' . $n . '. ' . $titolo . '.</b> ' . $testo;
        }

        return $righe;
    }

    /**
     * @param array<string, mixed> $imp
     */
    private static function campiDelPasso(int $passo, array $imp, ConfigurazioneCampi $cfg): string
    {
        $frasi = [];
        foreach ($cfg->campiDelForm($passo) as $c) {
            $chiave = (string) $c['chiave'];
            $obbligatorio = $chiave === 'locandina' ? true : ($chiave === 'allegati' ? (bool) $imp['allegati_obbligatori'] : (bool) $c['obbligatorio']);
            $dettaglio = match ($chiave) {
                'richiedente' => ' (è già indicato e non si cambia)',
                'url_docente' => ': dove vuoi che si pubblichi; con l’elenco delle pagine scegli le caselle, oppure indichi un’altra pagina del sito DiBEST; senza elenco scrivi l’indirizzo web completo (http:// o https://)',
                'locandina' => ': un solo file PDF, JPG o PNG, obbligatorio; si pubblica con il nome «Locandina_titolo_breve»',
                'titolo' => ': compare in anteprima nella Homepage',
                'sottotitolo' => ': al massimo ' . (int) $imp['max_sottotitolo'] . ' caratteri',
                'descrizione' => ': al massimo ' . (int) $imp['max_descrizione'] . ' caratteri (grassetto e corsivo non contano; il contatore diventa rosso se superi il limite)',
                'destinatari' => ': scegli almeno uno tra Cittadinanza, Studenti universitari, Docenti e Personale tecnico amministrativo; se scegli <b>Cittadinanza</b> compare un riquadro sul Public Engagement con il link a pe.unical.it (si apre in una nuova scheda)',
                'allegati' => ': altri file PDF, JPG o PNG, fino a ' . (int) $imp['max_allegati'] . ' file',
                'immagini' => ': solo JPG o PNG, fino a ' . (int) $imp['max_immagini'] . ' file',
                'tag' => ': separati da virgola',
                'data_inizio_pubblicazione' => (int) $imp['giorni_minimi'] > 0 ? ': almeno ' . (int) $imp['giorni_minimi'] . ' giorni dopo oggi' : ': non può essere passata',
                default => '',
            };
            $frasi[] = '<b>' . self::pulito((string) $c['etichetta']) . '</b>' . ($obbligatorio ? '' : ' (facoltativo)') . $dettaglio;
        }

        return ($frasi === [] ? 'Niente da compilare.' : implode('; ', $frasi) . '.')
            . ($passo === 5 ? ' Il peso massimo dei file è scritto nella pagina.' : '');
    }

    /**
     * Le colonne della tabella di monitoraggio che si completano dal pannello, una riga per colonna: lettera, nome, chi la compila e che cosa si scrive.
     * Si leggono da ConfigurazioneCampi, così la guida segue le intestazioni, i «a cura di» e le colonne aggiunte dall'amministratore.
     *
     * @return list<string>
     */
    private static function colonneDaCompletare(ConfigurazioneCampi $cfg): array
    {
        $tipo = ['si_no' => 'Si sceglie SI o NO (o si lascia vuota).', 'numero' => 'Un numero.', 'testo' => 'Testo libero.'];
        // D ed E (link) e le colonne dei destinatari arrivano già compilate con quello che ha indicato chi fa la richiesta (RegolePubblicazione / ServizioPubblicazioni::precompilazione)
        $dalRichiedente = array_merge(['d_url_pubblicazione', 'e_url_altre_pagine'], array_column(Costanti::DESTINATARI, 1));
        $righe = [];
        foreach ($cfg->colonne() as $c) {
            if (!$c['operatori']) {
                continue;
            }
            $cosa = str_contains($c['chiave'], '_ind_dibest_') ? 'Il valore dell’indicatore del Dipartimento (testo libero).' : ($tipo[$c['tipo']] ?? $tipo['testo']);
            $righe[] = '<b>' . ($c['lettera'] !== '' ? $c['lettera'] : 'Colonna aggiunta') . '</b> · ' . self::pulito($cfg->etichettaColonna($c['chiave'])) . '.'
                . ($c['a_cura_di'] !== '' ? ' A cura di ' . self::pulito($c['a_cura_di']) . '.' : '') . ' ' . $cosa
                . (in_array($c['chiave'], $dalRichiedente, true) ? ' Arriva già compilata con quello che ha indicato chi ha fatto la richiesta.' : '');
        }

        return $righe;
    }
}
